local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[5543] = { title = "Blutgefärbter Himmel", description = "Wehe jenen, die töricht genug sind, in die Pestländer zu wandern. Alle Arten der Verderbtheit bewohnen diese Wälder - von den fanatischen Anhängern des Scharlachroten Kreuzzugs, die jeden töten, der nicht das Zeichen der Kreuzzügler trägt, bis hin zur mordlustigen Geißel, die ihre Anzahl vergrößern will, indem sie ihre Ränge mit Untoten füllt.\n\nSogar die Tierwelt wurde in wilde, menschenfressende Bestien verwandelt. Ich bitte Euch, die zu vernichten, die vom Firmament aus zuschlagen: die Seuchenfledermäuse.", objectives = "Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5544] = { title = "Aassammlung", description = "Meine Essensvorräte gehen zur Neige, $R. Ich schäme mich zuzugeben, dass ich möglicherweise nicht genug Nahrung habe, um sie mit Euch zu teilen.\n\nKönnt Ihr einem alten Mann bei einer einfachen Aufgabe helfen? Hier in der Umgebung sind Aaswürmer die einzigen Tiere, die von den Verheerungen der Seuche unbeeinflusst blieben. Wenn sie auch ziemlich langweilig schmecken, kann das Fleisch der Würmer doch leicht monatelang aufbewahrt werden. Ich werde einige hundert Pfund benötigen, um meine Vorräte für den kommenden Winter aufzustocken!", objectives = "Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5545] = { title = "Ein Bündel Probleme", description = "Ich habe hier ein echtes Problem. Ich habe einen Liefertermin für eine Bestellung Holz und mir läuft die Zeit davon. Die Wölfe und Bären nördlich von hier haben meine Arbeiter von den Holzbündeln verjagt, die sie bereits gefällt hatten.\n\nIch habe bereits mit Deputy Rainer darüber gesprochen, dass die Tiere entfernt werden müssen, aber ich brauche jemanden, der das Holz für mich holt. Wenn Ihr acht Holzbündel für mich holen würdet, könnte ich den Termin vielleicht noch einhalten.", objectives = "Bringt 8 Holzbündel zu Raelen beim Holzfällerlager des Osttals.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5561] = { title = "Kodozusammentrieb", description = "Bibbly glaubt, dass er der einzige Goblin in Desolace sei, der weiß, wie man Geld macht. Tja, die einzige Karawane, die mutig genug ist, diese Gebiete zu bereisen, verlässt sich auf mich. Nachdem ich gelernt habe, wie man alternde und sterbende Kodos mit meinem Kodokombobulator verjüngt und kontrolliert, sind die Karawanenbesitzer Cork und Rigger mit mir eine Partnerschaft eingegangen.\n\nNehmt den Kombobulator und wendet ihn auf jeden beliebigen alten, alternden oder sterbenden Kodo an; er wird das Biest in einen gezähmten Kodo verwandeln und es zwingen, Euch zu folgen. Wenn Ihr einen Kodo gezähmt habt, bringt ihn zu mir her.", objectives = "Bringt fünf gezähmte Kodos sowie den Kodokombobulator zu Smeed Scrabblescrew bei Scrabblescrews Lager.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5581] = { title = "Portale der Legion", description = "Seht - die Hand von Iruxos. Ein wirklich grausiger Anblick.\n\nIhr müsst sie besitzen, wenn die Dämonenportale im Mannoroc-Koven gebannt werden sollen... und genau darum bitte ich Euch nun. Die Bedrohung durch die Dämonen steigt stetig und wir müssen diese Portale schließen, um die Flut der Dämonen, die in diese Welt eindringen, zu stoppen. Viel Glück, $N... und nehmt Euch vor den Portalwächtern in Acht.", objectives = "Verbannt 6 Portale in Mannorocs Koven und kehrt dann zu Taiga Wisemane nach Shadowprey zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5582] = { title = "Gesunde Großdrachenschuppe", description = "Dies ist eine Schuppe von einem verseuchten Großdrachen-Jungtier. Aber im Gegensatz zu den anderen pockennarbigen, eiternden Schuppen an dem kleinen Biest ist diese rare Schuppe gesund und unbeschädigt.\n\nBetina Bigglezink wird eine Probe davon für Forschungen haben wollen.", objectives = "Bringt die gesunde Großdrachenschuppe zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5601] = { title = "Schwester Pamela", description = "Ich bin während des großen Krieges aus Lordaeron geflohen und hatte das Glück, entkommen zu können, bevor die Geißel durch meine Heimat fegte und sie zu einem verseuchten Alptraum machte! Ich hatte Glück, aber meine Familie nicht. Ich fürchte, dass sie während der Schlacht von Darrowshire getötet wurden.\n\nDarrowshire ist ein Dorf in den östlichen Königreichen, eingebettet in die südlichen Hügel dessen, was heutzutage Östliche Pestländer genannt wird. Würdet Ihr Euch dorthin begeben und nach meiner Familie suchen? Ich vermisse sie so sehr, besonders meine kleine Schwester Pamela.\n\nBitte, sucht sie für mich!", objectives = "Sucht Pamela Redpath in Darrowshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5621] = { title = "Gewänder des Mondes", description = "Ich brauche Eure Hilfe, $n. Ich kann hier nicht weg, denn ich muss hier die anderen Schüler unterweisen, doch Ihr könntet einer unserer verwundeten Schildwachen direkt südlich von Dolanaar helfen. Sie wurde beim Patrouillieren der Stadt verletzt und benötigt unsere Hilfe. Ihr Name ist Shaya.\n\nWenn Ihr sie findet, heilt ihre Wunden, und stärkt dann ihren Körper mit Euren Zaubern. Das wird sie zumindest etwas länger vor Schaden bewahren, wenn es wieder hart auf hart kommt. Kehrt zu mir zurück, nachdem Ihr Eure Pflicht gegenüber Elune erfüllt habt.", objectives = "Sucht die Schildwache Shaya und heilt ihre Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Laurna Morninglight in Dolanaar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5622] = { title = "Elune geneigt", description = "$N, sobald Eure Aufgaben hier in Shadowglen abgeschlossen sind, müsst Ihr nach Dolanaar reisen. Dort werdet Ihr Laurna Morninglight finden. Sie wird Euch weiter in den Dingen Elunes unterweisen und bei ihr werdet Ihr Euch Eure ersten Gewänder verdienen, die Eure Position als $GPriester:Priesterin; von Elune kennzeichnen.\n\nSeid vorsichtig und möget Ihr auf Euren Reisen beschützt werden.", objectives = "Sprecht mit Laurna Morninglight in Teldrassil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5623] = { title = "Dem Licht geneigt", description = "Ich grüße Euch, $Gjunger Priester:junge Priesterin;. Die Zeit ist gekommen, mehr über unsere Religion zu lernen. Nachdem Ihr Eure Aufgaben hier in Nordhain abgeschlossen habt, sucht bitte Priesterin Josetta in Goldhain auf. Sie kann Euch noch mehr beibringen und hat gehört, dass Ihr in den Wegen des Lichts gut voranschreitet. Sie freut sich darauf, Euch weiter unterrichten zu können.", objectives = "Sprecht mit der Priesterin Josetta im Wald von Elwynn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5624] = { title = "Gewänder des Lichts", description = "Normalerweise stelle ich den Gefolgsleuten des Lichts eine kleine Herausforderung, um ihre Fertigkeiten zu prüfen. Ich möchte sehen, ob sie es wert sind, ihre ersten Roben zu tragen - sie sind ein Zeichen, dass die Kirche $gden Priester:die Priesterin; nach außen hin trägt und unterstützt.\n\nDoch hier ist die Situation etwas anders. Einer der Bürger von Goldhain sah eine verletzte Wache nahe dem See östlich von hier. Er heißt Roberts. Sucht ihn, heilt ihn, stärkt seinen Körper und kehrt hierher zurück. Wenn Ihr das für mich tun könnt, dann werde ich Eure Prüfung als bestanden ansehen.", objectives = "Sucht die Wache Roberts und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Priesterin Josetta in Goldhain zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5625] = { title = "Gewänder des Lichts", description = "Normalerweise wird etwa zu dieser Zeit die Macht in einem von Euch geprüft, um zu sehen, ob er würdig genug ist, jene Roben zu tragen, die seinen Platz in der Kirche anzeigen. Doch um ehrlich zu sein, gibt es wichtigere Dinge, um die ich mich kümmern muss. Bürger von Kharanos kamen gerade hierher und erzählten mir von einem verletzten Gebirgsjäger direkt außerhalb der Stadt im Süden - sein Name ist Dolf.\n\nWenn Ihr Dolf heilt und ihm 'Seelenstärke' gebt, werde ich das als erfolgreiche Prüfung ansehen. Wie klingt das?", objectives = "Sucht den Gebirgsjäger Dolf und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Maxan Anvol in Kharanos zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5626] = { title = "Dem Licht geneigt", description = "He! $n! Habt Ihr einen Moment Zeit?\n\nIhr seid dem Licht jetzt lange genug gefolgt, um den Weg zu Maxan Anvol in Kharanos zu finden. Er wird Euch mehr über den Weg beibringen, dem Ihr folgt, und wenn Ihr Euch als würdig erweist, wird er Euch Eure ersten Roben geben, die Eure Position als $GPriester:Priesterin; kennzeichnen.\n\nAlso dann mal los! Sobald Ihr hier fertig seid, geht durch den Tunnel - er wird auf Euch warten.", objectives = "Sprecht mit Maxan Anvol in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5627] = { title = "Sterne von Elune", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5628] = { title = "Heimkehr", description = "Ah, ja, hallo, $n? Ich freue mich, dass Ihr auf ein kurzes Gespräch hereinschaut. Ihr seid weit fort von zu Hause, und das in so jungen Jahren - ich bewundere einen solchen Ehrgeiz. Ich wünschte, ich hätte den Mut gehabt, durch die Welt zu reisen, als ich noch jünger war.\n\nEine Priesterin Eures Ordens war vor nicht allzu langer Zeit hier und hat nach Euch gesucht. Sie sagt, Ihr müsstet dringend in den Tempel des Mondes in Darnassus zurückkehren und mit Priesterin Alathea sprechen - es hatte etwas mit Eurer Ausbildung zu tun. Ich würde nicht zu lange trödeln, wenn es irgendwie geht.", objectives = "Sprecht mit der Priesterin Alathea in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5629] = { title = "Heimkehr", description = "Hallo, $n. Ich weiß, dass Ihr damit beschäftigt wart, unserem Volk zu helfen, aber Ihr müsst Euch auch Zeit für Euch selbst nehmen. Die Priesterin Alathea hat jemanden hergeschickt, um nach Euch zu suchen. Es scheint, dass Ihr die Aufmerksamkeit unserer Ältesten erregt habt, und sie sind der Meinung, dass Ihr für größere Dinge bereit seid. Begebt Euch zum Tempel des Mondes in Darnassus und sucht dort nach Alathea. Sie wird Euch erwarten. Viel Glück, und möge Elune mit Euch sein.", objectives = "Sprecht mit der Priesterin Alathea in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5630] = { title = "Heimkehr", description = "Hallo da, $GJungchen:Mädel;. Es ist gut zu sehen, dass Ihr entfernte Länder weit und breit bereist. Ich will Euch nicht beleidigen, aber viele Eurer Art vertragen das kalte Klima normalerweise nicht gut. Schön zu sehen, dass Ihr aus härterem Holz geschnitzt seid.\n\nVor nicht allzu langer Zeit war eine Eurer Priesterinnen hier und hat nach Euch gesucht - sie sagte so etwas in dem Sinne, dass Ihr eine Priesterin Alathea im Tempel des Mondes in Darnassus aufsuchen solltet. Sagte, es wäre wichtig und Ihr solltet Euch bald dorthin begeben.", objectives = "Sprecht mit der Priesterin Alathea in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5631] = { title = "Heimkehr", description = "Eine Priesterin hat kürzlich unsere Hallen besucht und Euch gesucht, $R. Sie sagte, sie hätte den Auftrag, Euch zu finden, und dass Ihr so bald wie möglich zum Tempel des Mondes in Darnassus zurückkehren solltet. Wenn Ihr ankommt, sucht Priesterin Alathea auf - sie wird Euch mehr berichten.\n\nDas Licht sei mit Euch, $n.", objectives = "Sprecht mit der Priesterin Alathea in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5632] = { title = "Heimkehr", description = "Oh, aber ja, natürlich. Hallo, $n. Eine Botin von Eurem Orden war vor nicht allzu langer Zeit hier und hat nach Euch gesucht. Sie erwähnte, dass in Darnassus etwas Wichtiges geschieht und dass Ihr so bald wie möglich zum Tempel des Mondes zurückkehren sollt. Wenn Ihr dort ankommt, sprecht mit Priesterin Alathea. Ich glaube, es hat etwas damit zu tun, dass Ihr so gute Fortschritte beim Verständnis unserer Bräuche macht.\n\nWie gesagt, kehrt nach Darnassus zurück, sobald Ihr könnt.", objectives = "Sprecht mit der Priesterin Alathea in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5633] = { title = "Heimkehr", description = "Seid gegrüßt, $GJungchen:Mädel;. Es ist schön, Euch hier in unseren großen Hallen zu sehen. Ein Segen sei mit Euch und Eurer Art.\n\nWährend Ihr durch unsere Länder gereist seid, kam eine Priesterin Eures Tempels her, die nach Euch suchte. Sie sagte, dass Ihr so bald wie möglich zum Tempel des Mondes zurückkehren sollt. Es tut mir Leid, dass ich Euch nicht mehr berichten kann, aber es klang wichtig. Wenn Ihr zum Tempel kommt, sprecht mit Priesterin Alathea.", objectives = "Sprecht mit der Priesterin Alathea in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5634] = { title = "Verzweifeltes Gebet", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5635] = { title = "Verzweifeltes Gebet", description = "Ihr habt die Aufmerksamkeit unserer Vorgesetzten erregt, $N. Sie bitten, dass Ihr so bald wie möglich zur Kathedrale des Lichts in Stormwind reist. Anscheinend sind sie der Meinung, dass Ihr Euch bereits würdig erwiesen habt und bereit seid, Eure Ausbildung weiterzuführen. Wenn Ihr dort anlangt, sucht nach der Hohepriesterin Laurena. Sie kann Euch weitere Anweisungen geben. Viel Glück, und möge das Licht mit Euch sein.", objectives = "Sprecht mit der Hohepriesterin Laurena in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5636] = { title = "Verzweifeltes Gebet", description = "Elune segne Euch, $R. Ich hoffe, dass Euer Licht Euch findet und Euch heute gut schützt.\n\nEiner Eurer Priester war vor nicht allzu langer Zeit hier und suchte nach Euch. Er erwähnte, dass Ihr sobald wie möglich zur Kathedrale des Lichts zurückkehren und mit der Hohepriesterin Laurena sprechen sollt. Es scheint, als hättet Ihr Euch wacker geschlagen, dass Ihr eine solche Aufmerksamkeit erlangt. Ich würde hier nicht allzu viel Zeit verbringen - Eure Leute brauchen Euch.", objectives = "Sprecht mit der Hohepriesterin Laurena in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5637] = { title = "Verzweifeltes Gebet", description = "Die Zeit ist für Euch gekommen, nach Stormwind zu gehen, $N. Die Hohepriesterin Laurena in der Kathedrale des Lichts möchte mit Euch sprechen. Es muss etwas sehr Gutes oder sehr Schlechtes sein, wenn die Hohepriesterin Euch persönlich dort sehen will, aber ich denke, dass Ihr selbst nur Gutes getan habt und dass es eine gute Sache ist, dass sie mit Euch sprechen möchte.\n\nVerschwendet hier aber nicht allzu viel Zeit. Ich an Eurer Stelle würde mich umgehend auf den Weg machen.", objectives = "Sprecht mit der Hohepriesterin Laurena in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5638] = { title = "Verzweifeltes Gebet", description = "Vor kurzer Zeit kam einer Eurer Priester her und suchte nach Euch, $R. Er sagte, dass ich Euch zur Kathedrale des Lichts schicken solle, wenn ich Euch sehen würde. Er sagte, es sei sehr wichtig, aber ich an Eurer Stelle würde mir trotzdem nicht allzu viele Sorgen machen. Seine Haltung erschien positiv ... als ob es gute Neuigkeiten wären. Auf jeden Fall solltet Ihr Euch beeilen, wenn Ihr meine Meinung wissen wollt.\n\nElune sei mit Euch, $R.", objectives = "Sprecht mit der Hohepriesterin Laurena in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5639] = { title = "Verzweifeltes Gebet", description = "Ihr werdet in Stormwind gebraucht, $N! Die Hohepriesterin dort, Laurena, sagt, es sei an der Zeit für Euch zu beweisen, dass Ihr der nächsten Stufe Eurer Ausbildung würdig seid. Verschwendet nicht zu viel Zeit auf dem Weg dorthin. Ihr könnt sie in der Kathedrale des Lichts im Zentrum der Stadt finden. Überbringt Ihr meine Wünsche und beweist, wie würdig Ihr eines solchen Rufes seid. Das Licht sei mit Euch, $N.", objectives = "Sprecht mit der Hohepriesterin Laurena in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5641] = { title = "Furchtlos", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5642] = { title = "Schattenwache", description = "In Orgrimmar geht etwas Wichtiges vor, $N.\n\nNormalerweise sind die Boten, die hier durchkommen und nach Trollpriestern suchen, recht umgänglich. Dieses Mal schienen sie jedoch in großer Eile zu sein. Trödelt nicht zu lange in Thunder Bluff herum. Ich würde so schnell wie möglich zum Tal der Geister zurückkehren.", objectives = "Sprecht mit Ur'kyo in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5643] = { title = "Schattenwache", description = "Wie viele unserer eigenen Priester werdet Ihr von Eurem Stamm durch die Initiationsriten geführt. Diese Riten lehren Priester häufig besondere Fähigkeiten, die wichtig für ihr Überleben sind. Ich spüre, dass die Zeit jetzt an Euch ist, jetzt, in diesem Augenblick. Ihr müsst zum Tal der Geister in Orgrimmar zurückkehren und mit Ur'kyo sprechen. Was er Euch lehrt, kann für die Zukunft sehr wichtig sein.", objectives = "Sprecht mit Ur'kyo in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5644] = { title = "Verschlingende Seuche", description = "Ah, ein wundervoller Tag für Euch, $N. Aufgrund der Lektionen, die Ihr gelernt habt, kann ich sehen, dass die Zeit gekommen ist, Euch zu Aelthalyste zurückzuschicken. Es gibt Dinge, die nur sie Euch beibringen kann, und auch das nur, wenn Ihr Euch als würdig erweist.\n\nIch werde die Überraschung für Euch nicht verderben, aber ich erinnere mich daran, wie es war, als ich ein junger Priester war und etwas über die wahre Macht lernte ... die göttliche Macht. Ja, das waren noch Zeiten.\n\nKehrt zu Aelthalyste nach Undercity zurück, $N. Sie erwartet Euch im Kriegsviertel.", objectives = "Sprecht mit Aelthalyste in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5645] = { title = "Furchtlos", description = "$N, Euer Hohepriester Rohan erwartet Euch zu einer Audienz in Ironforge. Beeilt Euch, Eure nächste Prüfung rückt schnell näher. Auch wenn ich wünschte, dass ich Zeuge der besonderen Riten Eures Volkes sein könnte, ist mein Platz doch hier. Aber möge das Licht während Eurer Reisen mit Euch sein. Rohan sollte sich noch im Mystikerviertel befinden, wenn Ihr die Stadt erreicht. Er wird Euch erwarten.", objectives = "Sprecht mit Hohepriester Rohan in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5646] = { title = "Verschlingende Seuche", description = "Aelthalyste bezeugt unserem Volk großen Respekt, indem sie unsere Leute zur weiteren Ausbildung zu mir schickt, und nun tue ich dasselbe für ihren Stamm.\n\nKehrt nach Undercity zurück, $N. Dort, im Kriegsviertel, wartet sie auf Euch und ist bereit, Euch mehr über Euer Volk und seine Wege zu lehren. Begebt Euch dorthin und zögert nicht lange.", objectives = "Sprecht mit Aelthalyste in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5647] = { title = "Furchtlos", description = "Euer Volk ist sehr stark, $N. Wir sind stolz darauf, Euch Verbündete nennen zu können. Mit jedem Sonnenuntergang nähert Ihr und Eure Art Euch nicht nur Euren wahren Wurzeln, sondern seid auch immer sicherer, dass Ihr in sehr vielen Belangen auf dem richtigen Weg seid. Das muss Euch ein so wunderbares Gefühl geben.\n\nErst vor kurzem erhielten wir eine Nachricht aus Ironforge. Sie besagte, dass Ihr dorthin zurückkehren und mit dem Hohepriester Rohan im Mystikerviertel sprechen sollt. Ich würde ihn nicht warten lassen. Möge Elune Eure Reisen leiten.", objectives = "Sprecht mit Hohepriester Rohan in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5648] = { title = "Gewänder der Spiritualität", description = "Ihr seid bereit für Eure erste Prüfung, $N. Südlich von Klingenhügel, direkt vor der Stadt, wurde eine Grunzerin verletzt, als sie einige von Proudmores alten Truppen bekämpfte. Es geht ihr nicht allzu gut und es wäre wirklich gut, wenn einer unserer Art ihr helfen könnte. Sucht sie - ihr Name ist Kor'ja -, heilt ihre Wunden und gebt ihr den Segen unserer Vorfahren.\n\nWenn Ihr das tut, sehe ich das als ausreichenden Beweis dafür an, dass Ihr bereit seid, unseren Pfad weiter zu beschreiten.", objectives = "Findet die Grunzerin Kor'ja und heilt ihre Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Tai'jin in Klingenhügel zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5649] = { title = "Der Spiritualität geneigt", description = "Ja, Mann. Unser Volk hat sich der Horde angeschlossen, weil sie gut für uns ist. Die da sind loyal und lehren uns viel über Dinge wie Ehre. Aber unsere alten Gewohnheiten sterben nur langsam. Die Orcs mögen nicht alle unsere Traditionen billigen, aber das bedeutet nicht, dass wir einige davon nicht im Geheimen ausüben können.\n\nIhr wisst das, und darum schicke ich Euch zu Tai'jin in Klingenhügel. Sie wird Euch mehr über unsere Geschichte lehren. Sie wird Euch in den Wegen unseres Stammes unterrichten. Geht zu ihr, wenn Ihr bereit seid.", objectives = "Sprecht mit Tai'jin in Durotar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5650] = { title = "Gewänder der Dunkelheit", description = "Unsere Macht beziehen wir aus der Dunkelheit und dem Schatten, $n, doch das ist nicht Eure einzige Rolle. Ihr habt erkannt, dass es von Vorteil ist, sich in der Heilkunst auszukennen. Das ist weise. Doch bevor Ihr die Dunkelheit kennen lernen könnt, müsst Ihr erst das Licht kennen. Und daher habe ich eine Prüfung für Euch.\n\nNördlich des Friedhofs befindet sich eine verwundete Todeswache - Todeswache Kel. Er hat uns seit geraumer Zeit vor Gnollen beschützt und braucht Heilung. Doch Ihr müsst auch seinen Körper stärken, bevor er seinen Dienst wieder aufnehmen kann. Tut beides mit Euren Zaubern und kehrt dann zu mir zurück.", objectives = "Findet die Todeswache Kel und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt zum dunklen Kleriker Beryl in Brill zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5651] = { title = "Der Dunkelheit geneigt", description = "Es gibt viele Lektionen, die die Verlassenen durch Erfahrung gelernt haben... Dinge, die einige Völker allenfalls erahnen können. Und obwohl unser Weg in Dunkelheit liegt, werdet Ihr feststellen, dass sehr viele Dinge sowohl vom Licht als auch von der Dunkelheit abhängen. Eure Lektionen sollen Euch lehren, beides zu nutzen... mit Umsicht. Aber beachtet meine Worte: vergesst nie, wir wurden in die Verderbnis gezwungen und der Fäulnis überlassen wie ein Stück Aas. Die Dunkelheit ist unser Heim.\n\nSucht den Dunklen Kleriker Beryl in Brill auf, wenn Ihr bereit seid, mehr zu erfahren.", objectives = "Sprecht mit dem Dunklen Kleriker Beryl in Tirisfal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5652] = { title = "Verhexung der Schwäche", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5654] = { title = "Verhexung der Schwäche", description = "Es ist an der Zeit, Euch mit Ur'kyo zu treffen, $N. Er befindet sich im Tal der Geister in der Orc-Stadt. Geht dorthin und sprecht mit ihm. Es ist an der Zeit, dass Ihr mehr über die alten Wege unserer Art lernt. Es wird Zeit, dass Ihr in den Kreis eingeführt und zu einem wahren Priester unseres Stammes gemacht werdet.", objectives = "Sprecht mit Ur'kyo in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5655] = { title = "Verhexung der Schwäche", description = "Ich wurde hergeschickt, um sicherzustellen, dass Ihr Euch nicht zu sehr von der Heimat entfernt, $n. Sie haben mich geschickt, um sicherzustellen, dass Ihr nach Hause zurückkehrt, da Ur'kyo, der größte unserer Priester, mit Euch zu sprechen wünscht. Begebt Euch dorthin. Begebt Euch zum Tal der Geister in der Stadt der Orcs und sprecht mit Ur'kyo. Er wartet auf Euch.", objectives = "Sprecht mit Ur'kyo in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5656] = { title = "Verhexung der Schwäche", description = "Es erwärmt immer mein nicht sterbendes Herz, Priester aus allen Kulturen zu sehen, die durch die Welt ziehen. Zu wissen, dass Macht existiert, die nicht arkan und sehr wohl in unserer Reichweite ist. Daher ist es mir eine Ehre, Euch nach Hause zu schicken, $n.\n\nUr'kyo, Euer großer Priester in Orgrimmar, bittet um Eure Anwesenheit. Ihr findet ihn im Tal der Geister.", objectives = "Sprecht mit Ur'kyo in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5657] = { title = "Verhexung der Schwäche", description = "Nach Hause. Kehrt nach Hause zurück, $R.\n\nEuer spiritueller Anführer Ur'kyo bittet Euch, zu ihm zurückzukehren und mit ihm über den Weg zu sprechen, den Ihr geht.\n\nBegebt Euch zum Tal der Geister in der großen Hordenstadt Orgrimmar. Dort werde Ihr ihn finden.", objectives = "Sprecht mit Ur'kyo in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5658] = { title = "Berührung der Schwäche", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5660] = { title = "Berührung der Schwäche", description = "Ihr seid weit weg von zu Hause, $C. Ihr werdet dort gebraucht, dort, in Eurer Stadt unter dem Boden. Eure Meisterin, diejenige, die Ihr Aelthalyste nennt, braucht Euch dort. Genau wie bei meinem Stamm gibt es dort Dinge, die Ihr nur von ihr lernen könnt. Bleibt nicht zu lange hier. Ihr solltet Euch zum Kriegsviertel begeben, so schnell ein Zeppelin Euch tragen kann.", objectives = "Sprecht mit Aelthalyste in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5661] = { title = "Berührung der Schwäche", description = "Ihr seid weit weg von zu Hause, hier in Bloodhoof, $N. Ich wurde hierher geschickt, um Priester meines eigenen Stammes zu finden und sie zurückzuschicken, um mit unseren Anführern zu sprechen, aber das bedeutet nicht, dass ich Euch nicht auch helfen kann.\n\nIch habe gehört, dass der Geist Eurer führenden Priesterin möchte, dass alle Verlassenen zu ihr kommen - es gibt Dinge, die Ihr lernen müsst.\n\nTrefft Euch mit Aelthalyste im Kriegsviertel, in Eurer Stadt.", objectives = "Sprecht mit Aelthalyste in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5662] = { title = "Berührung der Schwäche", description = "Mein Respekt gilt Euch und Eurer Art, $N. Normalerweise lehre ich nur die meines eigenen Stammes. Eure Lektionen kommen von Aelthalyste in der Stadt, die einst Lordaeron genannt wurde.\n\nIhr solltet zur ihr zurückkehren, wenn Ihr die Fähigkeiten erlernen wollt, die Euch von anderen Glaubensrichtungen abgrenzen.\n\nBegebt Euch ins Kriegsviertel in Undercity und sucht dort nach Eurer Meisterin.", objectives = "Sprecht mit Aelthalyste in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5663] = { title = "Berührung der Schwäche", description = "Aelthalyste schickte eine Nachricht an alle ihre Priester. Wir sollen die Jüngeren unseres Ordens für die weitere Ausbildung nach Undercity schicken. Wenn Ihr Euch wahrlich zu unseren Gläubigen zählt, dann solltet Ihr auch dorthin zurückkehren.\n\nIhr könnt Aelthalyste im Kriegsviertel in Undercity finden.", objectives = "Sprecht mit Aelthalyste in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5672] = { title = "Elunes Anmut", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5673] = { title = "Elunes Anmut", description = "Ihr wisst, dass Ihr jederzeit zu jedem unserer Lehrer Zugang habt, $n, aber es gibt einige Dinge, die wir nicht an Euch weitergeben können. Eines dieser Dinge sind die Lehren der Göttin Elune. Sie verleiht ihren Getreuen spezielle Fähigkeiten, und wenn ich mich nicht irre, ist es an der Zeit, dass Ihr nach Hause zu Eurem Tempel des Mondes zurückkehrt, um geprüft zu werden.\n\nKehrt dorthin zurück, wenn Ihr könnt, und sprecht mit der Priesterin Alathea.", objectives = "Sprecht mit der Priesterin Alathea in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5674] = { title = "Elunes Anmut", description = "Ein wunderbarer Tag ist gekommen, $n. Ihr habt das Alter erreicht, in dem unsere $gPriester:Priesterinnen; in Fähigkeiten ausgebildet werden, die nur die Nachtelfen kennen. Aber es ist nicht an mir, Euch auszubilden. Ihr müsst zum Tempel des Mondes zurückkehren und mit der Priesterin Alathea sprechen, sobald Ihr Eure Angelegenheiten hier abgeschlossen habt. Sie wird Euch prüfen, um sicher zu sein, dass Ihr bereit seid, und erst dann wird sie Euch Elunes Anmut lehren.", objectives = "Sprecht mit der Priesterin Alathea in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5675] = { title = "Elunes Anmut", description = "Die Zeit verrinnt, $gJungchen:Mädel;. Es ist an der Zeit, dass Ihr nach Darnassus heimkehrt. Die Priesterin Alathea ließ uns wissen, dass Ihr dorthin zur Ausbildung zurückkehren sollt. Es scheint, als wärt Ihr bereit, getestet zu werden, so wie jene, die dem Licht dienen. Ihr solltet Euch dorthin begeben, sobald Ihr könnt. Alatheas Nachricht besagte, dass sie im Tempel des Mondes auf Euch wartet. Viel Glück.", objectives = "Sprecht mit der Priesterin Alathea in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5676] = { title = "Arkane Rückkopplung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5677] = { title = "Arkane Rückkopplung", description = "So gern ich Euch auch unsere eigenen speziellen Lehren des Lichts zeigen würde, so ist dies doch nicht an uns. Ihr müsst zurück nach Stormwind, zu Eurer eigenen Art, $N... zumindest vorerst. Glaubt mir, es war nicht böse gemeint. Wenn Ihr zur Hohepriesterin Laurena in die Kathedrale des Lichts zurückkehrt, werdet Ihr verstehen, worüber ich spreche... Die Zeit ist für Euer Volk gekommen, Euch auf die Zukunft vorzubereiten, Euch von den anderen abzuheben, die einem ähnlichen Weg folgen.", objectives = "Sprecht mit der Hohepriesterin Laurena in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5679] = { title = "Verschlingende Seuche", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5680] = { title = "Schattenwache", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5713] = { title = "Ein Schuss, ein Treffer", description = "Ich war mit einer wichtigen Nachricht auf dem Weg nach Auberdine, als ich von dem Furbolg Marosh und seinen Fährtenlesern angegriffen wurde. Während des Angriffs wurde ich vergiftet, wodurch ich kaum noch stehen konnte. Ich kann ein Gegengift herstellen, aber es wird eine Zeit dauern, bis es bereit ist.\n\nIch möchte Euch bitten, mich zu verteidigen, bis ich das Gegengift anwenden kann. Ich werde Euch, so gut es geht, mit meinem Bogen helfen.\n\nFalls wir überleben, kann ich meine Botschaft nach Auberdine überbringen, während Ihr mit Onaeya bei Maestras Posten sprecht, um sie von diesem Vorfall zu unterrichten.", objectives = "Schützt die Schildwache Aynasha und sprecht dann mit Onaeya bei Maestras Posten in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5721] = { title = "Die Schlacht um Darrowshire", description = "Nun, $N, Ihr werdet an der Schlacht von Darrowshire teilnehmen und Joseph Redpath retten.\n\nPlatziert dieses Reliktbündel auf dem Marktplatz von Darrowshire, und die Geister von Darrowshire werden sich erheben. Nehmt an der Schlacht teil und sorgt dafür, dass die folgenden zwei Dinge eintreten: Davil muss den Tod von Horgus überleben und Redpath muss überleben, um erst verdorben und dann besiegt zu werden.\n\nNachdem Ihr den verderbten Redpath besiegt habt, wird seine Seele gerettet sein. Sprecht mit ihm und kehrt dann zu seiner Tochter Pamela zurück.", objectives = "Legt das Reliktbündel auf den Marktplatz von Darrowshire.\n\nVerhindert Davil Lightfires Tod, bis Horgus stirbt.\n\nVerhindert Captain Redpaths Tod, bis Redpath der Verderbte erscheint.\n\nBesiegt Redpath den Verderbten.\n\nSprecht mit dem Geist von Josef Redpath, sobald er auf dem Marktplatz erscheint, und sprecht dann mit Pamela in ihrem Zuhause.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5722] = { title = "Die Suche nach dem verloren gegangenen Ranzen", description = "Die Troggs sind nicht das Einzige, das Magatha im Ragefireabgrund interessierte. Sie hatte gehört, dass einer ihrer Diener, ein gewisser Maur Grimmtotem, im Abgrund etwas Sonderbares gefunden haben soll, nur leider schaffte er es nicht mehr, lebend herauszukommen, um ihr davon zu berichten. Sie möchte, dass Maurs Leiche - falls sie noch existiert - geborgen wird ... und auch jegliche Hinweise auf das, was er entdeckt haben könnte, als er versuchte, mit den Troggs zu sprechen.\n\nBringt Magatha Gegenstände, die sie interessieren könnten, dann wird sie sich bestimmt mit einer Belohnung nicht kleinlich zeigen.\n\nBegebt Euch noch einmal in den Abgrund im dunkelsten Teil von Orgrimmar.", objectives = "Sucht im Ragefireabgrund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5723] = { title = "Die Kraft des Feindes wird auf die Probe gestellt", description = "Unter der Stadt Orgrimmar haben stämmige Kreaturen, als Troggs bekannt, damit begonnen, sich aus den Tiefen unterhalb der lavagefüllten Tunnel an die Oberfläche zu wühlen. Wie es ihrer grundgütigen Art entspricht, hatte Magatha Frieden mit diesen Kreaturen schließen wollen, doch die Troggs stürzten sich auf ihre Diplomaten und töteten sie. Magatha lässt sich eine solche Behandlung des Taurenvolks nicht gefallen und betrachtet die Kreaturen jetzt als eine Gefahr für die gesamte Horde.\n\nSie bittet Euch, der Gefahr durch die Troggs ein Ende zu machen, bevor sie die Horde von unten überwältigen. Geht zum Ragefireabgrund und vernichtet sie alle.", objectives = "Sucht in Orgrimmar nach dem Ragefireabgrund, tötet dann 8 Ragefire-Troggs und 8 Ragefire-Schamanen und kehrt anschließend zu Rahauro in Thunder Bluff zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5724] = { title = "Wiederbeschaffung des verloren gegangenen Ranzens", description = "Unter dem Körper des Tauren findet Ihr einen Ranzen. Er hält ihn immer noch fest an sich gedrückt, als hätte er ihn beim Angriff der Troggs schützen wollen.\n\nIhr befreit den Ranzen aus seinem Klammergriff und verstaut ihn bei Eurer eigenen Ausrüstung, dann bereitet Ihr Euch darauf vor, die Tunnel zu verlassen und zu Rahauro in Thunder Bluff zurückzukehren.", objectives = "Bringt den Grimmtotemranzen zu Rahauro nach Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5725] = { title = "Die Macht der Zerstörung...", description = "Viele Angehörige der Legion bedenken ihre Anhänger mit Geschenken, wie Ihr bestimmt wisst. Manche dieser Geschenke wären nach Ansicht der Dunklen Fürstin besser in der Hand von Leuten aufgehoben, die... weniger Visionen haben.\n\nEine Sekte des Schattenrates, die sich Searingblade nennt und sich in den Höhlen unterhalb Orgrimmars versteckt, ist ein Musterbeispiel dafür. Die Fürstin sagte mir, dass Mitglieder der Searingblade in den Besitz zweier sehr mächtiger Zauberbücher gelangt seien... und sie möchte sich diese Bücher von ihnen 'borgen'. Ihr werdet sie ihr beschaffen.", objectives = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5726] = { title = "Verborgene Feinde", description = "Eines werde ich in meinen Reihen auf keinen Fall dulden, $N: Verräter. Ich wäre allerdings töricht, würde ich meine Trümpfe einfach so ausspielen. Die Geschwüre der Verderbnis in unserem Land würden nicht tief genug herausgeschnitten und die Infektion würde sich noch verschlimmern.\n\nAber Ihr, ein junger Abenteurer, könntet dorthin gehen, wo es meinen Agenten nicht möglich ist... könntet die Wahrheit ans Licht bringen... herausfinden, wer wirklich hinter dieser Bestie steckt.\n\nWenn Ihr mutig genug seid, geht zur Knochenhöhle östlich von Orgrimmar, besorgt mir die Insignie eines Offiziers der Burning Blade dort und kehrt zu mir zurück.", objectives = "Bringt die Insignie eines Offiziers zu Thrall nach Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5727] = { title = "Verborgene Feinde", description = "Und jetzt lasst uns sehen, ob die Insignie, die Ihr gefunden habt, der Mühe wert ist.\n\nIn der Stadt gibt es einen Hexenmeister, der seiner Meinung nach mein Vertrauen genießt. Er weiß allerdings nicht, dass ich gewahr bin, wem er wirklich die Treue hält. Tatsächlich ist er der Anführer der Burning Blade. Aber stürzt Euch jetzt nicht übereilt in einen Kampf mit ihm. Er könnte nützlich sein und wir werden ihn gegen unsere Feinde einsetzen.\n\nBringt diese Insignie zu ihm in die Kluft der Schatten hier in Orgrimmar. Sprecht mit ihm, seht, ob er Euch für einen der Ihren hält, und kommt dann zu mir zurück.", objectives = "Bringt Neeru Fireblade die Insignie des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Burning Blade seid, und kehrt dann zu Thrall nach Orgrimmar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5728] = { title = "Verborgene Feinde", description = "Hmmm, Anführer der Searingblade... das beunruhigt mich zutiefst. Wenn sie es sind, die für Neeru zählen, dann sollten sie auch unser erstes Ziel sein. Dieser Satyr... Bazzalan, und der andere, den Neeru erwähnte... Was war er doch gleich, ein Hexenmeister? Sie müssen vernichtet werden.\n\nKehrt zur Kluft der Schatten zurück und begebt Euch in den Ragefireabgrund, $N. Findet diese beiden Anführer der Searingblade und tötet sie. Aber seid vorsichtig, damit Neeru nicht erfährt, wer das getan hat. Er muss Euch auch weiterhin für $gseinen Kampfgenossen:seine Kampfgenossin; halten.", objectives = "Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5729] = { title = "Verborgene Feinde", description = "Ich glaube, unser nächster Schritt sollte sein, Euch in Neerus Nähe unterzubringen. Falls er wirklich so beunruhigt ist, wie die Berichte vermuten lassen, könnten wir zwei Fliegen mit einer Klappe schlagen. Erstens könntet Ihr mehr über den Rat oder zumindest die Searingblade in Erfahrung bringen, und zweitens könnte er Euch möglicherweise genug vertrauen, um Euch zu bitten, ihm zu helfen. Vielleicht wird er Euch für jemanden halten, der die Lücken füllt, die der Tod der Anführer gerissen hat.\n\nKehrt zur Kluft zurück und sprecht noch einmal mit ihm, aber haltet Euch bedeckt.", objectives = "Sprecht mit Neeru Fireblade in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5730] = { title = "Verborgene Feinde", description = "Ihr seid einer meiner Offiziere! Macht Euch bereit, $C. Ich werde Euch bald benötigen.\n\nDie Zeit, die ich für die Searingblade aufgebracht hatte, war jetzt vielleicht reine Zeitverschwendung, aber das bedeutet nicht, dass die restlichen Pläne des Schattenrates darunter leiden müssen. Ich werde tun, was ich kann, um den Schaden hier im Ragefireabgrund zu begrenzen. In der Zwischenzeit sollen meine Agenten im Brachland und in Ashenvale mit der Arbeit an unserem neuesten Geheimplan beginnen. Kommt bald zu mir zurück.", objectives = "Sprecht in Orgrimmar mit Thrall und berichtet ihm, was Ihr erfahren habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5741] = { title = "Szepter des Lichts", description = "Die Burning Blade in der Festung Thunder Axe im Osten sollen Gerüchten zufolge das Szepter des Lichts von den Naga erworben haben. Die Legenden besagen, dass das Szepter dazu fähig ist, ganze Städte unter den Ozeanen verschwinden zu lassen. Wir dürfen nicht zulassen, dass die Burning Blade solche Macht besitzen.\n\nUm das zu gewährleisten, müsst Ihr selbst das Szepter bergen! Es ist im Besitz eines Sehers der Burning Blade, der das Szepter in einem der Wachtürme von Thunder Axe studiert.", objectives = "Besorgt das Szepter des Lichts und bringt es zurück zu Azore Aldamort am Turm in Ethel Rethor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5742] = { title = "Erlösung", description = "Ihr habt sehr hart gearbeitet. Ruht Eure müden Knochen aus und erlaubt mir, mich korrekt vorzustellen.", objectives = "Hört Euch an, was Tirion Fordring zu sagen hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5761] = { title = "Vernichtung der Bestie", description = "Die vorrangige Aufgabe, die mir unser großer Kriegshäuptling übertragen hat, ist die Vernichtung der Kreaturen, die dafür verantwortlich sind, dass sich der dämonische Einfluss in der großen Stadt unseres Herrschers einnisten konnte. Die Burning Blade sind eine Gefahr, aber es gibt auch noch andere. Die Searingblade zum Beispiel, die sich im Ragefireabgrund niedergelassen haben, versuchen insgeheim unschuldige Mitglieder der Horde auf ihre Seite zu ziehen.\n\nUm sie aufzuhalten, muss ihr Anführer beseitigt werden - eine Teufelswache namens Taragaman der Hungerleider.\n\nTötet ihn, und sein Herz wird Thrall beschwichtigen, dessen bin ich mir sicher.", objectives = "Begebt Euch in den Ragefireabgrund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Fireblade nach Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5762] = { title = "Hemet Nesingwary Jr.", description = "Ich habe hier eine Sendung für einen alten Kunden von mir, einen Zwerg namens Hemet Nesingwary. Die Sendung war wochenlang unterwegs und Hemet ist schon längst wieder weg. Er sagte, dass er ins Schlingendorntal gehen wolle, um die Bestien dort zu jagen, aber er ließ mir etwas Geld da und wollte, dass ich ihm seine Sendung schicke, sobald es mir möglich sei. \n\nHemet ist ein reicher Zwerg und man sollte sich mit den Reichen ruhig gut stellen, findet Ihr nicht auch? Also... könntet Ihr die Sendung für mich zustellen?\n\nWie ich hörte, soll Hemet im Schlingendorntal nördlich von Grom'gol ein Lager aufgeschlagen haben.", objectives = "Bringt Kravels Kiste zu Hemet Nesingwary ins Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5763] = { title = "Jagd im Schlingendorntal", description = "Vor langer Zeit kam ein Zwerg in dieses Land. Sein Name war Hemet, und er kam, um große Wildtiere zu jagen. Sein Geschick mit Flinten war außergewöhnlich, und wir haben viele Tage zusammen auf der Jagd verbracht. Sogar die Feindschaft zwischen unseren Völkern war vergessen.\n\nAls er Desolace verließ, um ins Schlingendorntal zu gehen, schwor ich, ihn irgendwann einmal wieder willkommen zu heißen, um mit ihm zusammen auf die Jagd zu gehen. Dieser Zeitpunkt ist jetzt gekommen.\n\nBringt Hemet dieses Kodohorn. Er wird wissen, dass es von mir kommt. Ihr findet ihn im Schlingendorntal, nördlich des Basislagers von Grom'gol.", objectives = "Bringt Roons Kodohorn zu Hemet Nesingwary ins Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5781] = { title = "Von vergessenen Erinnerungen", description = "Wenn Ihr Taelan helfen wollt, zurückzubekommen, was er verloren hat, müsst Ihr Gegenstände aus seiner Vergangenheit zusammentragen.\n\nDer Erste dieser Gegenstände ist ein Spielzeug, das ich ihm zu seinem 7. Geburtstag schenkte. Es war sein wertvollster Besitz. Ein winziger Kriegshammer, die exakte Kopie meines eigenen.\n\nAls man mich wegen Verrats verbannte, erzählte ihm seine Mutter, dass ich gestorben sei. Man brachte ihn zu meinem angeblichen Grab beim Tiefgewölbe, wo er den Hammer zusammen mit seiner Erinnerung an mich begrub - für immer.\n\nIhr müsst Euch zum Tiefgewölbe begeben und Taelans Hammer holen.", objectives = "Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5801] = { title = "Feuerfeder geschmiedet", description = "Ihr braucht zwei Barren Thorium und eine kräftige und sehr heiße Wärmequelle, um den Schaft des Schlüssels zu schmieden. Das Thorium müsst Ihr Euch selbst besorgen, aber mit der Wärmequelle kann ich Euch helfen.\n\nWestlich von hier im Un'Goro Krater liegt der Feuerfedergrat - ein brodelnder Vulkan. Der Lavasee an seiner Spitze ist heiß genug, um Thorium und Knochen miteinander zu verschmelzen. Ihr habt mit Eurem Gold eine Form erstanden, die Ihr einfach nur in den See tauchen müsst. Die Lava erledigt dann den Rest.\n\nDas war's von meiner Seite. Um Euren Schlüssel fertig zu stellen, müsst Ihr noch einmal mit Arbington sprechen.", objectives = "Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuerfedergrats im Un'Goro Krater. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden.\n\nBringt den unvollendeten Skelettschlüssel dann zum Alchimisten Arbington an der Chillwindspitze in den Westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5802] = { title = "Feuerfeder geschmiedet", description = "Ihr braucht zwei Barren Thorium und eine kräftige und sehr heiße Wärmequelle, um den Schaft des Schlüssels zu schmieden. Das Thorium müsst Ihr Euch selbst besorgen, aber mit der Wärmequelle kann ich Euch helfen.\n\nWestlich von hier im Un'Goro Krater liegt der Feuerfedergrat - ein brodelnder Vulkan. Der Lavasee an seiner Spitze ist heiß genug, um Thorium und Knochen miteinander zu verschmelzen. Ihr habt mit Eurem Gold eine Form erstanden, die Ihr einfach nur in den See tauchen müsst. Die Lava erledigt dann den Rest.\n\nDas war's von meiner Seite. Um Euren Schlüssel fertig zu stellen, müsst Ihr noch einmal mit Dithers sprechen.", objectives = "Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuerfedergrats im Un'Goro Krater. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden.\n\nBringt den unvollendeten Skelettschlüssel zu Apotheker Dithers im Bollwerk, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5803] = { title = "Arajs Skarabäus", description = "Araj der Beschwörer herrscht von dem ruinierten Herzen der Stadt aus über Andorhal. Wir wissen, dass er der ehemalige Kopf der Scholomance war, bevor er die Stadt an sich riss. Um den Schlüssel fertig zu stellen, benötigen wir sein Signet - Skarabäus genannt. Es wird den Kopf des Schlüssels bilden.\n\nMacht Euch auf den Weg ins Herz von Andorhal und brecht mit seiner Herrschaft über die Stadt, jetzt wo er für uns erreichbar ist. Nehmt den Skarabäus aus seinem Phylakterium, sobald er vernichtet ist!\n\nDer Schlüssel zu Scholomance erwartet Euch, $n!", objectives = "Zerstört Araj den Beschwörer und bringt Arajs Skarabäus zum Alchimisten Arbington an der Chillwindspitze in den westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5804] = { title = "Arajs Skarabäus", description = "Araj der Beschwörer herrscht von dem ruinierten Herzen der Stadt aus über Andorhal. Wir wissen, dass er der ehemalige Kopf der Scholomance war, bevor er die Stadt an sich riss. Um den Schlüssel fertig zu stellen, benötigen wir sein Signet - Skarabäus genannt. Es wird den Kopf des Schlüssels bilden.\n\nMacht Euch auf den Weg ins Herz von Andorhal und brecht mit seiner Herrschaft über die Stadt, jetzt wo er für uns erreichbar ist. Nehmt den Skarabäus aus seinem Phylakterium, sobald er vernichtet ist!\n\nDer Schlüssel zu Scholomance erwartet Euch, $n!", objectives = "Vernichtet Araj den Beschwörer und bringt Arajs Skarabäus zum Apotheker Dithers im Bollwerk, in den westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5805] = { title = "Willkommen!", description = "Willkommen bei WORLD OF WARCRAFT!\n\nAls besonderes Dankeschön dafür, dass Ihr die WORLD OF WARCRAFT COLLECTOR'S EDITION erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Merissa Stilwell im Nordhaintal einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in der Welt von WarCraft!", objectives = "Bringt Merissa Stilwell den Nordhaingeschenkgutschein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5821] = { title = "Leibwache zu mieten", description = "Unter normalen Umständen würden Rigger und ich unseren Kodo an den Kolkarzentauren vorbeiführen. Aber ab und zu sind Kriegstrommeln der Zentauren zu hören, und dann machen wir sofort Halt. Es ist nicht gut fürs Geschäft, tot zu sein!\n\nIch sag Euch was, $C, wenn Ihr uns heil am Dorf der Kolkar vorbeibringt, soll es Euer Schaden nicht sein.\n\nEs ist nur eine kurze Strecke und Ihr müsst lediglich dafür sorgen, dass die Karawane intakt bleibt, dann könnt Ihr Euch Eure Belohnung bei Smeed Scrabblescrew abholen. Ihr findet ihn ein Stück weiter die Straße runter. Wir haben geschäftlich miteinander zu tun.", objectives = "Bringt Gizeltons Karawane am Dorf der Kolkarzentauren vorbei. Sprecht in Scrabblescrews Lager mit Smeed, um Eure Belohnung zu erhalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5841] = { title = "Willkommen!", description = "Willkommen bei WORLD OF WARCRAFT!\n\nAls besonderes Dankeschön dafür, dass Ihr die WORLD OF WARCRAFT COLLECTOR'S EDITION erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Yori Crackhelm im Coldridgetal einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in der Welt von WarCraft!", objectives = "Bringt Yori Crackhelm den Coldridgetal-Geschenkgutschein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5842] = { title = "Willkommen!", description = "Willkommen bei WORLD OF WARCRAFT!\n\nAls besonderes Dankeschön dafür, dass Ihr die WORLD OF WARCRAFT COLLECTOR'S EDITION erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Orenthil Whisperwind in Shadowglen einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in der Welt von WarCraft!", objectives = "Bringt Orenthil Whisperwind den Shadowglen-Geschenkgutschein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5843] = { title = "Willkommen!", description = "Willkommen bei WORLD OF WARCRAFT!\n\nAls besonderes Dankeschön dafür, dass Ihr die WORLD OF WARCRAFT COLLECTOR'S EDITION erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Magga im Tal der Prüfungen einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in der Welt von WarCraft!", objectives = "Bringt Magga den 'Tal der Prüfungen'-Geschenkgutschein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5844] = { title = "Willkommen!", description = "Willkommen bei WORLD OF WARCRAFT!\n\nAls besonderes Dankeschön dafür, dass Ihr die WORLD OF WARCRAFT COLLECTOR'S EDITION erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Vorn Skyseer im Camp Narache einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in der Welt von WarCraft!", objectives = "Bringt Vorn Skyseer den 'Camp Narache'-Geschenkgutschein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5845] = { title = "Von verlorener Ehre", description = "Der Orden der Silberhand wurde gar sehr geschwächt, als Uther sein gewaltsames Ende fand.\n\nDer Junge hat durchgehalten, so lange er konnte. Er wurde bis zum vom Krieg zerrissenen Weiler Northdale zurückgetrieben, und dort stellte er sich zu seinem letzten Kampf.\n\nWar noch irgendjemand aus dem Orden am Leben, fragte er sich - und spielte das überhaupt noch eine Rolle?\n\nMit diesem Gedanken im Kopf schmetterte Taelan die Standarte des Ordens zu Boden und entsagte allem, was er gelernt hatte. Auf dem blutgetränkten Boden Northdales ließ er seine Ehre zurück.\n\nIhr müsst nach Northdale reisen und das Symbol der verlorenen Ehre finden.", objectives = "Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5846] = { title = "Von Liebe und Familie", description = "Als Taelan noch ein Kind war, unternahmen wir mit der Familie oft Ausflüge nach Caer Darrow. Bei unserem letzten Besuch malte ein Künstler namens Renfray ein Porträt von uns, wie wir am Strand posierten. Das ist die schönste Erinnerung, die ich an Taelan und Karandra habe. Denn es war just dieser Moment, wo ich meine Frau und meinen Sohn in den Armen hielt, dass ich eine Liebe und Verbundenheit mit meiner Familie spürte, die ich seitdem nie wieder erlebt habe.\n\nFalls dieses Gemälde noch existiert, müsst Ihr es finden.\n\nBegebt Euch zur in Trümmern liegenden Insel Caer Darrow und seht nach, ob das Gemälde des Künstlers noch da ist.", objectives = "Begebt Euch zur Insel Caer Darrow im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5847] = { title = "Willkommen!", description = "Willkommen bei WORLD OF WARCRAFT!\n\nAls besonderes Dankeschön dafür, dass Ihr die WORLD OF WARCRAFT COLLECTOR'S EDITION erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Claire Willower in Deathknell einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in der Welt von WarCraft!", objectives = "Bringt Claire Willower den Deathknell-Geschenkgutschein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5848] = { title = "Von Liebe und Familie", description = "Das Gemälde... Es hing jahrelang an der Wand meiner Werkstatt - in der Kaserne des Ordens.\n\nNachdem Tirions Prüfung vorüber war, wusste ich, dass ich das Gemälde nicht mehr dort für alle sichtbar hängen lassen konnte. So versteckte ich es an einem Ort, an dem es niemand vermuten würde.\n\nGeht nach Stratholme und begebt Euch tief in die heutige Scharlachrote Bastion. Sucht dort nach einem Gemälde, auf dem unsere Zwillingsmonde abgebildet sind. Kratzt die Farbe weg, bis mein Meisterwerk zum Vorschein kommt, 'Von Liebe und Familie'.\n\nMöge das Licht Eure Taten leiten.", objectives = "Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der Scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.\n\nBringt das Gemälde zu Tirion Fordring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5861] = { title = "Myranda suchen", description = "Ihr habt alles getan, um das ich Euch bislang bat, $n. Jetzt fehlt nur noch ein Schritt auf Eurem Weg zur Erlösung.\n\nIhr müsst die gesammelten Gegenstände Taelan aushändigen. Leider werden Euch Taelan und seine Scharlachroten Kreuzzügler angreifen, sobald sie Euer ansichtig werden.\n\nEs gibt nur eine Möglichkeit, meine Nachricht zu übermitteln, und zwar durch Täuschung.\n\nIm Süden findet Ihr Uthers Grabmal. Myranda, eine alte und getreue Vertraute von mir, lebt jetzt dort - geht zu ihr. Zeigt ihr die Gegenstände, dann wird sie Euch helfen.", objectives = "Begebt Euch zu Uthers Grabmal in den Südlichen Pestländern. Zeigt Myranda der Vettel Tirions Geschenk.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5862] = { title = "Scharlachrote Täuschung", description = "Ich bin eine Illusionistin, wie Ihr das nennen würdet. Ich könnte zwar eine Illusion erschaffen, die es Euch ermöglichen würde, Hearthglen zu betreten, aber seid gewarnt, meine Kräfte haben Grenzen.\n\nSolltet Ihr Euch zu weit aus diesem Land entfernen, lassen die Effekte dieser Illusion nach. Der Zauber selbst bedarf Unmengen an Konzentration und Kraft meinerseits, und deshalb kann ich den Effekt nur für kurze Zeit aufrechterhalten.\n\nKommt wieder zu mir, wenn Ihr bereit seid.", objectives = "Sprecht mit Myranda, um die scharlachrote Illusion zu erhalten. Begebt Euch nach Hearthglen, während Ihr unter dem Einfluss der scharlachroten Illusion steht, und übergebt dem Hochlord Taelan Fordring Tirions Geschenk.\n\nHearthglen liegt im Norden, Taelan dürfte sich in der Burg Mardenholde aufhalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5863] = { title = "Das Truppenlager der Dünenbrecher", description = "Erst kürzlich ist eine große Gruppe nomadischer Oger in Tanaris eingetroffen. Südlich von hier haben sie einen großen Bereich der Wüste in Besitz genommen und ein Truppenlager aufgeschlagen. Mehrere kleinere Gruppen durchstreifen momentan die Wüste, einige davon sind in die alten Troll-Ruinen eingedrungen.\n\nDas Truppenlager der Dünenbrecher muss zerstört werden! Wir dürfen nicht zulassen, dass diese Oger zu einer Streitmacht heranwachsen.\n\nDer Anführer der Gruppe heißt Gor'marok der Verheerer. Ich bin mir sicher, dass es den Anfang vom Ende für die Oger bedeuten würde, wenn man ihnen den Anführer nimmt.", objectives = "Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5881] = { title = "Hinzurufen der Reserve", description = "Die Horde kümmert sich gut um ihre Truppen... seit dem großen Krieg ging es uns hier in Kalimdor sehr gut.\n\nIhr müsst mir einen Gefallen tun. Ich lasse einen Jungen namens Grish Longrunner den großen Aufzug im südlichen Brachland bewachen. Gebt ihm diesen Brief, er wird ihn wissen lassen, dass ich einen Ersatzmann angefordert habe, um ihn von seinem Dienst zu entbinden, damit er seine Familie besuchen kann. Er bat mich vor einer Weile darum und wird sich über diese Nachricht freuen.", objectives = "Maggran möchte, dass Ihr Grish Longrunner am großen Aufzug im Brachland einen Brief zustellt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
