quests[5892] = { title = "Vorräte der Eisenschachtmine", description = "Bevor die Schlacht begann, lagerten wir Vorräte für Dun Baldar in der Eisenschachtmine. Die Troggs, die dort hausten, waren kein Problem solange wir Ersatztruppen hatten, die die Mine bewachen konnten, aber da wir nun gegen die Horde kämpfen, können wir sie nicht mehr kontrollieren.\n\nWir brauchen die Vorräte in der Eisenschachtmine, $n. Betretet die Mine und bring mir eine Ladung.", objectives = "Bringt 10 Vorräte der Eisenschachtmine zum Rüstmeister der Allianz in Dun Baldar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5893] = { title = "Vorräte der Eisbeißermine", description = "Die Eisbeißermine im Norden war einst ein idealer Ort, um zusätzliche Vorräte zu lagern, aber da die Kämpfe mit den Sturmlanzen nun härter werden, haben wir nicht immer die notwendigen Soldaten über, um sie an der Mine zu positionieren und diese zu bewachen. Daher fällt die Kontrolle über diese Mine oft an die Allianz oder an Untergrundvölker...\n\nAber wir benötigen dennoch unsere Vorräte, $n! Geht zu der Eisbeißermine und bringt mir eine Ladung. Seid wachsam, was unsere Feinde anbelangt, die Übermacht in der Schlacht kann sich an jenem Ort schnell ändern...", objectives = "Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Horde in die Burg Frostwolf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5901] = { title = "Eine Plage komme über Euch", description = "Also, um Schmerz und Unfrieden über den Scharlachroten Kreuzzug zu bringen, möchte ich ihnen ihr wertvolles Sägewerk wegnehmen. Ich bin mir sicher, der Verlust einer solchen Ressource wird ihnen ziemlichen Schaden in Bezug auf Verteidigung und Wiederaufbau der Stadt für ihre Zwecke zufügen. Werdet Ihr mir helfen, $n?\n\nFangt an, indem Ihr diesen Krug zum Pestwald in den Östlichen Pestländern bringt. Füllt ihn mit den Termiten, die Ihr in ihren Hügeln überall im Wald findet. Kommt wieder, wenn Ihr eine ausreichende Menge habt.", objectives = "Wendet den leeren Termitenkrug auf die Termitenhügel in den östlichen Pestländern an. Sobald Ihr 100 Pestland-Termiten gesammelt habt, kehrt zu Mickey Levine am Bollwerk in Tirisfal zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5902] = { title = "Eine Plage komme über Euch", description = "Da wir jetzt jede Menge Termiten haben, bringt dieses stahlverstärkte Fass zum Northridge-Sägewerk südlich von Hearthglen. Ihr werdet es westlich der Straße finden, die Euch in die Stadt hinauf führt.\n\nWenn Ihr dort seid, stellt Ihr das Fass in die Mitte des Sägewerkes, irgendwo weit oben, vielleicht auf eine Kiste oder sowas.\n\nNachdem Ihr es geöffnet habt, sollte sich der Rest von selbst erledigen. Kommt einfach hierher zurück und ich werde Euch dafür belohnen, dass Ihr mir geholfen habt.", objectives = "Sucht Euch einen geeigneten Ort in der Mitte des Northridge-Sägewerks in den Westlichen Pestländern, um das Fass mit den Pestland-Termiten abzustellen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5903] = { title = "Eine Plage komme über Euch", description = "Ich habe bereits viele Male versucht, den Scharlachroten Kreuzzug allein mit Gewalt auszulöschen, doch ohne Erfolg. Daher habe ich mich entschlossen, ihnen das Leben schwer zu machen.\n\nWenn Ihr bereit seid zu helfen, möchte ich, dass Ihr dieses Sägewerk mit der übelsten Termitenart verseucht, die je gefunden wurde.\n\nIm Pestwald, nahe dem einst großen Stratholme, gibt es eine Spezies, die die Seuche und auch die Geißel überlebt hat. Sucht ihre Hügel und füllt diesen Krug mit ihnen, damit wir sie darauf vorbereiten können, auf den Kreuzzug losgelassen zu werden.", objectives = "Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestland-Termiten gesammelt habt, kehrt zu Nathaniel Dumah am Chillwindposten in den Westlichen Pestländern zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5904] = { title = "Eine Plage komme über Euch", description = "Da wir jetzt die Termiten haben, bringt dieses stahlverstärkte Fass zum Northridge-Sägewerk südlich von Hearthglen. Ihr werdet es westlich der Straße finden, die Euch in die Stadt hinauf führt.\n\nWenn Ihr dort seid, stellt Ihr das Fass in die Mitte des Sägewerkes. Findet einen geeigneten Ort, vielleicht eine Kiste, und öffnet es dann. Die Termiten dürften dann ihre Arbeit tun und die Mühle für den Kreuzzug unbrauchbar machen.", objectives = "Sucht Euch einen geeigneten Ort in der Mitte des Northridge-Sägewerks in den Westlichen Pestländern, um das Fass mit den Pestland-Termiten abzustellen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5921] = { title = "Mondlichtung", description = "Alle Druiden sind in den hochheiligen Landen von Moonglade willkommen, ungeachtet der derzeitigen Spannungen im Zirkel des Cenarius zwischen dem Erzdruiden Staghelm und dem Bewahrer Remulos, dem Wächter von Moonglade. Jetzt, da Ihr den Weg der Klaue lernt, bringe ich Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr Moonglades Wissen oder Zuflucht sucht.\n\nAls Eure erste Lektion müsst Ihr nach Moonglade reisen und mit Dendrite Starblaze in Nighthaven über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, $gjunger Druide:junge Druidin;.", objectives = "Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5922] = { title = "Mondlichtung", description = "Alle Druiden sind in den hochheiligen Landen von Moonglade willkommen, Tauren wie Nachtelfen. Bewahrer Remulos - Moonglades Wächter - wacht über allen Druiden, die hier ihren Winterschlaf halten. Jetzt, da Ihr den Weg der Klaue lernt, bringe ich Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr Moonglades Wissen oder Zuflucht sucht.\n\nAls Eure erste Lektion müsst Ihr nach Moonglade reisen und mit Dendrite Starblaze in Nighthaven über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, $gjunger Druide:junge Druidin;.", objectives = "Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5923] = { title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bearwalker bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Staghelms Baum.", objectives = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5924] = { title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bearwalker bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Staghelms Baum.", objectives = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5925] = { title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bearwalker bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Staghelms Baum.", objectives = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5926] = { title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runetotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Thunder Bluff, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", objectives = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5927] = { title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runetotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Thunder Bluff, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", objectives = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5928] = { title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runetotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Thunder Bluff, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", objectives = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5929] = { title = "Großer Bärengeist", description = "Im nordwestlichen Teil von Moonglade liegt das Zuhause eines weisen und edlen Wesens, das wir den großen Bärengeist nennen. Er hat allen Druiden als Tutor und Mentor zur Seite gestanden, die das erste Mal wahres und natürliches Verständnis für den Bären entwickeln wollten. Alle Druiden suchen an irgendeinem Punkt ihres Lebens die Weisheit des Geistes und auch Ihr werdet keine Ausnahme sein.\n\nGeht nun zum großen Bärengeist und lernt, was er Euch beibringen wird. Wenn er mit Euch zufrieden ist, kehrt zu mir hier nach Nighthaven zurück. Wir werden dann sehen, ob Ihr die Lektionen, die er Euch gelehrt hat, wirklich verinnerlicht habt.", objectives = "Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5930] = { title = "Großer Bärengeist", description = "Im nordwestlichen Teil von Moonglade liegt das Zuhause eines weisen und edlen Wesens, das wir den großen Bärengeist nennen. Er hat allen Druiden als Tutor und Mentor zur Seite gestanden, die das erste Mal wahres und natürliches Verständnis für den Bären entwickeln wollten. Alle Druiden suchen an irgendeinem Punkt ihres Lebens die Weisheit des Geistes und auch Ihr werdet keine Ausnahme sein.\n\nGeht nun zum großen Bärengeist und lernt, was er Euch beibringen wird. Wenn er mit Euch zufrieden ist, kehrt zu mir hier nach Nighthaven zurück. Wir werden dann sehen, ob Ihr die Lektionen, die er Euch gelehrt hat, wirklich verinnerlicht habt.", objectives = "Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5931] = { title = "Zurück nach Darnassus", description = "Es ist an der Zeit für uns, getrennte Wege zu gehen, denn die Anwendung Eurer Lektionen bringt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Mathrengyl Bearwalker bewegt sich wirklich im Einklang mit der Natur, selbst wenn er gefährlich nahe der Orte ist, an denen das Gleichgewicht zusammengebrochen ist. Achtet auf seine Anweisungen und Ihr werdet bald die ersten Lektionen Eurer Rolle als Beschützer des Gleichgewichts beenden.\n\nGeht jetzt. Wir sehen uns wieder.", objectives = "Kehrt nach Darnassus zurück und sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5932] = { title = "Zurück nach Thunder Bluff", description = "Es ist an der Zeit für uns, getrennte Wege zu gehen, denn die Anwendung Eurer Lektionen bringt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Auch wenn die Tauren auf den Wegen des Cenarius als jung angesehen werden, wandelt Turak Runetotem doch mit großem Gleichgewicht in Gegenwart der Natur. Achtet auf seine Anweisungen und Ihr werdet bald die ersten Lektionen Eurer Rolle als Beschützer des Gleichgewichts beenden.\n\nGeht jetzt. Wir sehen uns wieder.", objectives = "Kehrt nach Thunder Bluff zurück und sprecht mit Turak Runetotem auf der Anhöhe der Ältesten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5941] = { title = "Rückkehr zu Chromie", description = "Ihr habt viele Relikte der Schlacht von Darrowshire gesammelt. Jedes Mal, wenn Ihr mit weiteren zurückgekehrt seid, sehnte sich mein Herz nach meinem Dorf... sehnte es sich danach, es vor seinem Schicksal zu bewahren.\n\nIch weiß, dass das nicht sein kann, aber Chromie, diese seltsame Gnomin in Andorhal, behauptet, es wäre möglich. Sie sagt, dass Ihr Darrowshire retten könnt!\n\nSie hat mich gebeten, die Relikte zu sammeln und sie von Euch zu ihr bringen zu lassen. Sie sagte, dass sie Euch im zerstörten Gasthaus von Andorhal erwartet.", objectives = "Bringt das Reliktbündel zu Chromie nach Andorhal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5942] = { title = "Versteckte Schätze", description = "Papa sagte, ich solle Euch diesen Schlüssel geben. Er sagte, er öffnet eine Truhe draußen hinter dem Haus.\n\nEr wollte außerdem, dass ich Euch danke. Habt Ihr ihm einen Gefallen getan? Habt Ihr ihm gesagt, dass Ihr meine Puppe gefunden habt?\n\nNun, hier ist jedenfalls der Schlüssel. Und habt Dank, $n. Danke! Ihr seid $gein sehr netter Mann:eine sehr nette Dame;!", objectives = "Bringt Josephs Schlüssel zu Josephs Truhe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5943] = { title = "Gizeltons Karawane", description = "Ihr seht fähig aus, $R. Vielleicht wollt Ihr Euch etwas Geld verdienen? Cork und ich haben mit dieser Karawane angefangen, um einen Haufen Geld zu scheffeln. Doch wir hatten keine Ahnung von den Gefahren, die das schnelle Geld mit sich bringen würde!\n\nDa vor uns liegt Mannorocs Koven ... normalerweise ignorieren die Dämonen uns, aber dieses Mal verängstigt irgendetwas die Kodos. Ich werde Euch dafür bezahlen, wenn Ihr die Karawane auf dem Weg an Mannorocs Koven vorbei beschützt. Sobald wir sicher daran vorbei sind, könnt Ihr Euch Eure Belohnung bei unserem Geschäftspartner Smeed in Scrabblescrews' Lager abholen.", objectives = "Geleitet Gizeltons Karawane durch Mannorocs Koven. Sprecht in Scrabblescrews Lager mit Smeed, um Eure Belohnung zu erhalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5944] = { title = "In den Träumen", description = "Über so lange Zeit war ich eine Marionette des obersten Kreuzzüglers. Welchen Grund gab es, gegen das anzukämpfen, was aus dem scharlachroten Kreuzzug geworden ist? Es ist Jahrzehnte her, doch die Erinnerungen an meinen Vater - diese kostbaren Erinnerungen - waren es, die mich am Leben erhielten.\n\nIch habe Träume, $gFremder:Fremde;. In diesen Träumen ist mein Vater bei mir. Er steht stolz an meiner Seite, während ich in den Orden aufgenommen werde. Wir bekämpfen Legionen der Geißel, Seite an Seite. Wir bringen der Allianz und Lordaeron Ehre.\n\nIch möchte nicht mehr träumen.\n\nBringt mich zu ihm.", objectives = "Geleitet Taelan Fordring aus Hearthglen hinaus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5961] = { title = "Der Champion der Bansheekönigin", description = "Es freut mich sehr, dass sich die Kampferprobten unserer Sache anschließen. Unsere Schar gewinnt mit jedem Tag an Größe und Stärke. Vielleicht seid Ihr bereit, Euren Mut auf die Probe zu stellen, $C?\n\nZu den ersten meiner Helden gehörte Nathanos, der heute Blightcaller genannt wird. In unseren Reihen gibt es kaum einen mit mehr Entschlossenheit oder Eifer.\n\nSucht in den Östlichen Pestländern nach ihm. Er wohnt in Marris Siedlung; ab und an streift er durch die dezimierten Ödländer und tötet jeden Abschaum der Geißel und der Allianz, den er aufspüren kann.", objectives = "Sprecht mit Nathanos Blightcaller in den Östlichen Pestländern. Es heißt, dass er sich in Marris Siedlung niedergelassen hätte.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[5981] = { title = "Tobende Riesen", description = "Vor rund 4000 Jahren rettete Tyrande Whisperwind die Frostsäblerkönigin aus den Händen tobender Riesen. Seither sind die Frostsäbler Verbündete der Nachtelfen.\n\nDoch die Riesen, die einst eine Gefahr für die Frostsäbler waren, gibt es noch immer, und das nicht allzu weit von hier entfernt. Man nennt sie Frosthagelriesen und sie haben das große Tal südlich von hier für sich beansprucht.\n\nBeweist Eure Treue zu den Frostsäblern. Tötet diese Riesen im Namen der Frostsäblerkönigin Shy-Rotam!", objectives = "Rivern Frostwind möchte, dass Ihr 4 Frosthagelriesen und 4 Frosthagelbewahrer besiegt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6001] = { title = "Körper und Herz", description = "Unmittelbar östlich von Auberdine liegen viele Moonkinhöhlen. In der Auberdine am nächsten gelegenen Höhle befindet sich ein Moonkinstein. Mondklaue, der Verteidiger des Steins, stellt sich Euch nur, wenn Mondstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die Ihr als einer der Klaue benutzen müsst.\n\nIhr habt Euch das Recht verdient, diesen Mondstaub des Cenarius zu benutzen, $N... jetzt zeigt mir, dass Ihr Euch das Recht verdient habt, die Kraft des Körpers und des Herzens zu besitzen, die man als Druide braucht!", objectives = "Benutzt den Mondstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\n\nSprecht mit Mathrengyl Bearwalker in Darnassus, wenn Ihr fertig seid.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6002] = { title = "Körper und Herz", description = "Auf Land westlich von Taurajo im Brachland - kurz bevor es in Mulgore übergeht - liegt ein Moonkinstein. Moonkin sind besondere Tiere, die nicht in diesen Breiten heimisch sind. Mondklaue, der Verteidiger des Steins, stellt sich Euch, wenn Lunarstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die Ihr als einer der Klaue benutzen müsst.\n\nIhr habt Euch das Recht verdient, diesen Lunarstaub des Cenarius zu benutzen, $N... jetzt zeigt mir, dass Ihr Euch das Recht verdient habt, die Kraft des Körpers und des Herzens zu besitzen, die man als Druide braucht!", objectives = "Benutzt den Lunarstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\n\nSprecht mit Turak Runetotem in Thunder Bluff, wenn Ihr fertig seid.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6004] = { title = "Offene Rechnungen", description = "Ich wurde als Späher ausgeschickt, um etwas Schaden anzurichten und die Kraft von Hearthglens Verteidigung auszukundschaften. Einige Leute der Allianz sind der Meinung, die kleine Stadt habe mehr als nur eine historische Bedeutung. Meine Aufgabe ist es nicht, diese Bedeutung in Frage zu stellen, aber dennoch sollte ich mich in meiner Verfassung erst erholen, bevor ich weitermache.\n\nWenn Ihr wollt, zahle ich Euch ein hübsches Sümmchen für Eure Hilfe. Fangt südlich von hier in dem Lager an, das sie in der Nähe des kleinen Bollwerks aufgeschlagen haben. Wenn Ihr stark genug seid, könnt Ihr mir vielleicht bei meinem vordringlichen Ziel helfen.", objectives = "Tötet 2 scharlachrote Sanitäter, 2 scharlachrote Jäger, 2 scharlachrote Magi und 2 scharlachrote Ritter, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6021] = { title = "Zaeldarr der Ausgestoßene", description = "Könnt Ihr Euch vorstellen, dass wir uns nach dem ganzen Ärger in den Pestländern... jetzt auch noch um Diebe sorgen müssen? Nicht einfach gewöhnliche Diebe, Troll-Diebe.\n\nUnd nicht einfach gewöhnliche Troll-Diebe. Tote Troll-Diebe!\n\nSie werden von diesem großen toten Troll namens Zaeldarr dem Ausgestoßenen angeführt, kommen nachts hierher und stehlen Leichen aus der Grube unten. Dann schaffen sie sie zu ihrem üblen Versteck für tote Trolle - dem Tiefgewölbe im Westen.\n\nGeht dorthin und schaltet Zaeldarr aus, $N. Ich habe seine Schandtaten satt!", objectives = "Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des Hoffnungsvollen Lichts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6022] = { title = "Töten zu einem bestimmten Zweck", description = "Ihr tötet zu einem bestimmten Zweck, solange Ihr in meiner Siedlung seid.\n\nEure erste Aufgabe ist es, meine Hunde zu füttern.\n\nNehmt diesen Mörser nebst Stößel und begebt Euch zu Corins Kreuzung. Dort angekommen findet Ihr Mitglieder der Geißel, die Ihr töten könnt, in recht großer Anzahl.. Aus ihren frischen Kadavern benötige ich lebendige Fäulnis. Nehmt diese lebendige Fäulnis, zermahlt sie im Mörser und lasst sie ruhen, bis sie gerinnt. Bringt die geronnene Fäulnis hierher.\n\nUnd bedenkt, Schwachkopf, dass lebendige Fäulnis der Untoten nicht lange 'lebendig' bleibt. Ihr müsst sie schnell töten!", objectives = "Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6023] = { title = "Offene Rechnungen", description = "Meine wahre Mission bestand darin, die äußeren Kräfte des Scharlachroten Kreuzzugs zu schwächen und dann Hearthglen zu infiltrieren, damit ich ihre Zahl abschätzen kann. In meiner Verfassung kann ich das immer noch nicht allein, vielleicht dürfte ich Euch ja erneut um Eure Unterstützung bitten, $N? Bevor ich entdeckt wurde, konnte ich die Informationen sammeln, dass der Kreuzzug zwei wichtige Mitglieder hat, die das Rückgrat ihrer Streitkräfte außerhalb der Stadt bilden: Jägerin Radley und Chevalier Durgen. Tötet sie, das bringt uns schon weiter. Sie müssten am Pass von Hearthglen außerhalb der Stadtgrenze sein.", objectives = "Besiegt Jägerin Radley und Chevalier Durgen, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6024] = { title = "Hameyas Bitte", description = "Tötet mich. Bevor es zu spät ist.\n\nIch bin Hameya. Auf der Reise nach Zul'Mashar aßen meine Geschwister und ich verdorbenes Fleisch... und wir veränderten uns. Wir sind infiziert.\n\nIch spüre bereits die Worte des Lichs, der mich bedrängt, dass ich nach Zul'Mashar gehen und noch mehr von meinem Volk infizieren soll. Ich kann nicht widerstehen, daher verfasste ich diese Schriftrolle, ehe es um meine Willenskraft geschehen ist.\n\nIch habe hinter dieser Gruft eine Truhe neben einem Wagen in der Erde vergraben, aber nur mein Schlüssel kann sie öffnen. Ich habe den Schlüssel. Wenn Ihr meinen Schatz möchtet, sucht mich.\n\nTötet mich. Bevor es zu spät ist.", objectives = "Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6025] = { title = "Offene Rechnungen", description = "Was? Wirklich? Ihr möchtet noch mehr wissen? Aber Ihr habt bereits so viel für mich getan, $N. Ich kann Euch unmöglich darum bitten, an meiner statt nach Hearthglen zu gehen.\n\nSeid Ihr sicher, $N? Hearthglen ist viel gefährlicher als der Pass - ich kann Euch weder Schutz noch Informationen geben, was Ihr da vorfinden könntet.\n\nAlso, wenn Ihr wirklich bereit seid, mir zu helfen, dann geht in die Stadt und sucht eine erhöhte Stelle, von der aus Ihr einen guten Überblick habt. Dort könnt Ihr ihre Zahl abschätzen und mir dann Bericht erstatten. Aber seid vorsichtig...", objectives = "Geht nach Hearthglen, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Deepshadow in den Westlichen Pestländern zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6026] = { title = "Das ist viel verlangt", description = "Diese Leute von der Argentumdämmerung haben den alten Smokey beauftragt, ein paar Abrissarbeiten für sie durchzuführen. Smokeys Mama hat keinen Trottel großgezogen. Wenn bares Gold auf den Tisch gelegt wird, ist Smokey stets zu Diensten. Das ist mein Motto!\n\nIch wäre bereit, den Profit mit Euch zu teilen, wenn Ihr mir ein wenig zuarbeiten wollt. Das ist der Plan: Ich geh rüber in den Pestwald und kennzeichne die Gebäude, die abgerissen werden müssen. Ihr sammelt die Komponenten für die Bomben. Wir treffen uns hier wieder, wenn Ihr alles habt. Abgemacht?", objectives = "Smokey LaRue möchte, dass Ihr 2 Thoriumbarren, 1 Goldrute, 8 hochexplosive Bomben und 8 instabile Auslöser beschafft.\n\nFür diese Gegenstände müsst Ihr einen Schmied und einen Ingenieur finden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6027] = { title = "Buch der Uralten", description = "$n, ich vertraue Euch den Edelstein der Schlange an. Legt diesen Edelstein auf der Insel Ranazjar nordwestlich von hier in die Hand der Schlangenstatue. Dadurch wird jener gerufen, der das 'Buch der Uralten' beschützt. Dieses Buch birgt die Geheimnisse der Naga. Geheimnisse, die seit Jahrhunderten gewahrt werden. Bringt mir dieses Buch, dann werden wir mehr über unsere schuppigen Widersacher erfahren!", objectives = "Beschafft das 'Buch der Uralten' und kehrt zu Azore Aldamort im Turm von Ethel Rethor zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6028] = { title = "Der Everlook-Bericht", description = "Ich suche ein verantwortungsbewusstes Individuum, das mir in einer kleinen, aber dennoch wichtigen Angelegenheit hilft. Ich bin hier als Vertreter der Argentumdämmerung und ihrer Interessen in der Lokalverwaltung von Everlook. Ich muss Argentumoffizier Pureheart im Chillwind-Lager einen Fortschrittsbericht zukommen lassen. Das ist weit entfernt von hier am südlichen Rand der Westlichen Pestländer.\n\nWenn ich so kühn sein darf - dies wäre eine perfekte Möglichkeit, Euch meiner Vorgesetzten vorzustellen und vielleicht etwas Arbeit von ihr zu bekommen!", objectives = "Bringt den Everlook-Bericht zu Argentumoffizier Pureheart im Chillwind-Lager in den westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6029] = { title = "Der Everlook-Bericht", description = "Ich suche ein verantwortungsbewusstes Individuum, das mir in einer kleinen, aber dennoch wichtigen Angelegenheit hilft. Ich bin hier als Vertreter der Argentumdämmerung und ihrer Interessen in der Lokalverwaltung von Everlook. Ich muss Argentumoffizier Garush beim Bollwerk einen Fortschrittsbericht zukommen lassen; das ist weit entfernt von hier am westlichen Rand der Westlichen Pestländer, östlich von Tirisfal.\n\nWenn ich so kühn sein darf - dies wäre eine perfekte Möglichkeit, Euch meinem Vorgesetzten vorzustellen und vielleicht etwas Arbeit von ihm zu bekommen!", objectives = "Bringt den Everlook-Bericht zu Argentumoffizier Garush im Bollwerk in den Westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6030] = { title = "Fürst Nicholas Zverenhoff", description = "Ein einsiedlerisches Medium namens Umbranse, das in dieser Gegend ansässig ist, hat der Argentumdämmerung ein literarisches Meistwerk geschenkt... es handelt sich vermutlich um die größte Sammlung mündlicher Überlieferungen, die je zu Papier gebracht wurde.\n\nFürst Nicholas Zverenhoff, einer der angesehensten Anführer der Dämmerung, ist ein brillanter Sprachwissenschaftler. Könntet Ihr ihm das für mich bringen - natürlich gegen eine Belohnung? Bei der Kapelle des Hoffnungsvollen Lichts, tief im östlichen Teil der Östlichen Pestländer - da hält er sich gerade auf.", objectives = "Bringt das Buch 'Studien zur Geistersuche' zu Fürst Nicholas Zverenhoff in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6031] = { title = "Runenstoff", description = "Wir in der Holzschlundfeste sind eigentlich ganz zufrieden. Wir mögen keine Fremden. Das ist gut für uns, aber schlecht für das Geschäft.\n\nEs ist noch nicht lange her, da kam eine Nachtelfenfreundin, die einen Runenumhang trug, auf die Holzschlundfeste. Runenstoff ist bei uns selten, aber der Umhang war so edel, dass mein Volk jetzt von mir verlangt, mehr Runenstoffkleidung zu fertigen.\n\nWerdet Ihr mir Runenstoff bringen? Wenn Ihr mir ausreichend beschafft, gebe ich Euch etwas im Tausch dafür.", objectives = "Bringt 30 Runenstoff zu Meilosh in der Holzschlundfeste.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6032] = { title = "Hochheiliger Stoff", description = "Die Einwohner der Holzschlundfeste mögen das Gefühl von Runenstoff auf der Haut, aber er ist nichts Hochheiliges für uns. Mondstoff dagegen ist hochheilig.\n\nBringt mir einen kleinen Vorrat dieses heiligen Stoffs und ich lehre Euch eine geheime Schneidertechnik.", objectives = "Bringt 2 Mondstoff zu Meilosh in der Holzschlundfeste.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6041] = { title = "When Smokey Sings, I Get Violent", description = "Während Ihr die Vorräte gesammelt habt, habe ich einige meiner Leute die Geißelbauwerke kennzeichnen lassen, die wir abreißen müssen.\n\nSo ist der Plan: Ich gebe Euch zehn Stecken meines speziellen Präparats. Ihr bringt sie rüber in den Pestwald und platziert sie in den Geißelbauwerken, die für die Sprengung markiert wurden.\n\n<Smokey schnippt mit den Fingern.>\n\nBing! So einfach ist das.", objectives = "Reist in den Pestwald, nordwestlich der Hoffnung des Lichts. Zerstört 8 Geißelbauwerke, indem Ihr Smokeys spezielles Präparat am Mal der Zerstörung in jedem Bauwerk benutzt. Smokey hat die Ziggurats und Schlachthäuser markieren lassen.\n\nWenn ihr die Bombe gelegt habt, dann verlasst das Bauwerk und staunt über Euer Geschick.\n\nÜbrigens, Smokeys spezielles Präparat ist recht ... instabil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6042] = { title = "Die kleinen Ärgernisse des Un-Lebens", description = "Man kann keine zwei Schritte von diesem Hof runter, ohne auf eine dieser grässlichen Fledermäuse zu stoßen. Ich möchte die Hunde ausführen und die Geißel abschlachten können, ohne dass mich diese elenden, schmutzigen Fledermäuse behelligen. Ich habe Wichtigeres mit meiner Zeit anzufangen, als tagein, tagaus sinnlos Fledermäuse zu töten. Ihr allerdings nicht.\n\nWas? Eure Ausbildung? Das ist Eure Ausbildung! Jetzt geht mir aus den Augen und kommt erst zurück, wenn Ihr eine ordentliche Menge dieser geflügelten Dämonen getötet habt! Enttäuscht mich nicht.", objectives = "Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr fertig seid.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6061] = { title = "Die Zähmung der Bestie", description = "Für uns als Tauren ist es wichtig, dass wir den Traditionen unserer Vorfahren folgen und gegen mächtige Kreaturen kämpfen. Wenn wir diese Kreaturen bezwingen, können wir ihre Geister aufnehmen und näher bei der Erdenmutter sein.\n\nAuf dieselbe Weise hilft es uns, eins mit der Natur zu werden, wenn wir ein Tier zähmen, damit es an unserer Seite kämpft. Ihr werdet auch irgendwann lernen, ein Tier Eurer Wahl zu zähmen. Aber alles erfordert Übung und Ihr müsst noch viel lernen. Nehmt als erstes diese Zähmrute. Ihr müsst einen ausgewachsenen Ebenenschreiter zähmen.", objectives = "Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6062] = { title = "Die Zähmung der Bestie", description = "Es ist eine bewundernswerte Fertigkeit, wenn man über die Natur gebietet. Als Jäger müsst Ihr lernen, wie man Macht und Kraft benutzt, die jeder Kreatur Eurer Wahl innewohnt.\n\nEs ist nicht einfach, Kontrolle über ein Tier zu erlangen. Ihr müsst diese Aufgabe mit großer Entschlossenheit verfolgen.\n\nAls erste Aufgabe nehmt diese Zähmrute und zähmt damit einen scheckigen Terroreber. Ihr findet sie in der Nähe von Klingenhügel. Übt Eure Fertigkeiten im Kampf mit dem Eber an Eurer Seite und kommt dann zu mir zurück.", objectives = "Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6063] = { title = "Die Zähmung der Bestie", description = "Als Jäger dürft Ihr niemals die Verantwortung vergessen, die Ihr tragt. Die Natur ist eine Kraft, die sich nicht Euren Wünschen beugt. Man muss sie respektieren und anerkennen als etwas Stärkeres als die eigene Existenz.\n\n$n, Ihr müsst beweisen, dass Ihr das verstanden habt, bevor Ihr die Fähigkeit erwerben könnt, Euch ein Tier als Gefährten zu zähmen.\n\nEure erste Aufgabe ist es, diese Zähmrute zu nehmen. Mit ihr könnt Ihr einen Waldweberlauerer zähmen. Zähmt ihn und übt Eure Fertigkeiten als Jäger.", objectives = "Benutzt die Zähmrute, um einen Waldweberlauerer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6064] = { title = "Die Zähmung der Bestie", description = "Hallo, $GBursche:Mädchen;! Ihr wollt also wissen, wie Ihr ein eigenes Tier bekommen könnt?\n\nGut, dann lasst uns anfangen. Wenn es um das Jagen geht, dann ist nichts wichtiger als Eure Ausrüstung, aber wir können ein andermal über meinen neuen Schrapnell-Blaster sprechen. Konzentrieren wir uns vorerst auf etwas, das Euch gewiss interessiert: ein Tier!\n\nAm besten lernt Ihr, wenn Ihr verschiedene Kreaturen als Gefährten ausprobiert und herausfindet, welche Ihr mögt. Sucht also einen großen Klippeneber und benutzt dann diese Zähmrute, um ihn zu zähmen.", objectives = "Benutzt die Zähmrute, um einen großen Klippeneber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6065] = { title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Sharpmane in Bloodhoof aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Yaw Sharpmane in Bloodhoof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6066] = { title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Scharfmähne im Dorf der Bluthufe aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Yaw Scharfmähne im Dorf der Bluthufe in Mulgore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6067] = { title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Sharpmane in Bloodhoof aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Yaw Sharpmane in Bloodhoof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6068] = { title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Thotar in Klingenhügel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6069] = { title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Thotar in Klingenhügel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6070] = { title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Thotar in Klingenhügel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6071] = { title = "Der Weg des Jägers", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Dazalar in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6072] = { title = "Der Weg des Jägers", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Dazalar in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6073] = { title = "Der Weg des Jägers", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Dazalar in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6074] = { title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildheart in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Grif Wildheart in Kharanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6075] = { title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildheart in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Grif Wildheart in Kharanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6076] = { title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildheart in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", objectives = "Sprecht mit Grif Wildheart in Kharanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6081] = { title = "Die Ausbildung des Tiers", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es auszubilden.\n\nReist nach Orgrimmar. Dort müsst Ihr mit Ormak Grimshot sprechen, einem unserer angesehensten Jäger. Er wird Euch die Fähigkeit verleihen, Euer neues Tier auszubilden. Ihr findet ihn nahe der Halle der Kriegerhelden.\n\nViel Glück, $N.", objectives = "Sprecht mit Ormak Grimshot in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6082] = { title = "Die Zähmung der Bestie", description = "Die letzte Kreatur, die Ihr zähmen müsst, wird dasselbe mit Euch versuchen: der gepanzerte Skorpid. Er schlägt schnell und selbstbewusst zu. Eine solche Macht zu kontrollieren ist Euer Schicksal als Jäger.\n\nWenn Ihr zurückkehrt verleihe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl zu zähmen. Diese Kreatur wird Euren Befehlen gehorchen. Unter Eurer Kontrolle wird Euer Tier an Eurer Seite Erfahrung sammeln. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", objectives = "Benutzt die Zähmrute, um einen gepanzerten Skorpid zu zähmen. Übt Eure Fertigkeiten und kehrt zu Thotar in Klingenhügel zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6083] = { title = "Die Zähmung der Bestie", description = "Der Vorteil, den Euch ein Tier gegen Eure Rivalen bietet, wird zur Kenntnis genommen, $n! Wenn Ihr Kontrolle über eine andere Kreatur erlangt, erhöht Ihr Eure eigene Kraft. Euer Tier muss sozusagen Euer verlängerter Arm werden.\n\nDie nächste Aufgabe führt Euch vom Land weg. Ihr findet die nächste Kreatur in den Gewässern vor der Küste. Sucht jenseits von Sen'jin nahe den Echoinseln. Sucht nach einem lebhaften Krebs, der Brandungskriecher genannt wird. Benutzt die Zähmrute, um ihn zu zähmen und übt dann Eure Fertigkeiten.", objectives = "Benutzt die Zähmrute, um einen Brandungskriecher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6084] = { title = "Die Zähmung der Bestie", description = "Diese Klippeneber sind recht bullig. Vielleicht möchtet Ihr etwas mit ein wenig mehr Grazie? Na gut, da hab ich genau das Richtige. Südlich und östlich von hier findet Ihr große weiße Katzen, die man Schneeleoparden nennt. Genau wie bei einem elegant geschnitzten Gewehr verbirgt sich hinter dem wunderschönen Äußeren ein kräftiger Kämpfer, der extremen Schaden zufügen kann. Ihr werdet feststellen, dass sie wesentlich agiler und schneller als Euer gezähmter Eber sind.\n\nNehmt diese Zähmrute und findet heraus, wie Euch der Schneeleopard gefällt.", objectives = "Benutzt die Zähmrute, um einen Schneeleoparden zu zähmen. Übt Eure Fertigkeiten und kehrt dann zu Grif Wildheart in Kharanos zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6085] = { title = "Die Zähmung der Bestie", description = "Vielleicht hättet Ihr gern eine Kreatur, die etwas mehr besitzt als nur rohe Kraft? Der Eisklauenbär ist ein ausgezeichneter Gefährte für einen angehenden Jäger wie Euch und östlich von Kharanos zu finden. Hier ist die Zähmrute. Probiert dieses Geschöpf als Euer Tier aus und findet heraus, wie es Euch gefällt!\n\nWenn Ihr zurückkehrt, gebe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man sie ganz nach Belieben ruft und wegschickt.", objectives = "Benutzt die Zähmrute, um einen Eisklauenbären zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6086] = { title = "Die Ausbildung des Tiers", description = "$N, Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr müsst die Fertigkeiten erlangen, es auszubilden.\n\nReist nach Ironforge und sucht die Halle der Waffen. Dort müsst Ihr mit Belia Thundergranite sprechen, einer unserer angesehensten Jägerinnen. Sie gibt Euch die Macht, Euer neues Tier auszubilden, also macht Euch auf den Weg, $GBursche:Mädchen;.\n\nBelia ist recht umgänglich, Ihr findet gewiss ihre Zustimmung. Viel Glück, $N.", objectives = "Sprecht mit Belia Thundergranite in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6087] = { title = "Die Zähmung der Bestie", description = "Ihr besitzt einen feurigen Geist, Jäger, und brennt schon auf Eure nächste Herausforderung.\n\nAls nächste Aufgabe müsst Ihr einen Wolf, der als Präriepirscher bekannt ist, zum Gefährten gewinnen. Diese Kreatur ist flink und furchtlos. Wenn Ihr diese Bestie als Euer Tier wollt, müsst Ihr diese Eigenschaften ebenfalls erlangen.\n\nIm Kampf werdet Ihr lernen, wie Ihr und Euer Tier ein Team werdet. Letztendlich müsst Ihr wie ein Wesen handeln, Muskel an Muskel.\n\nHier habt Ihr die Zähmrute, $n. Zähmt einen Präriepirscher und übt Eure Fertigkeiten.", objectives = "Benutzt die Zähmrute, um einen Präriepirscher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6088] = { title = "Die Zähmung der Bestie", description = "Die letzte Aufgabe, die ich für Euch habe, verlangt von Euch, dass Ihr eine Kreatur zähmt, die den Himmel bewohnt. Der Sturzflieger ist ein schwieriger Gegner, aber als Euer Verbündeter gibt er Euch seine scharfen Angriffe und seine bedrohliche Präsenz.\n\nWenn Ihr zurückkehrt gebe ich Euch durch den Willen der Erdenmutter die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl als Gefährten zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", objectives = "Benutzt die Zähmrute, um einen Sturzflieger zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6089] = { title = "Die Ausbildung des Tiers", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es zu trainieren.\n\nReist nach Thunder Bluff. Dort müsst Ihr mit Holt Thunderhorn sprechen, einem unserer angesehensten Jäger. Wenn er Euch für würdig befindet, gibt er Euch die Fähigkeit, Euer neues Tier auszubilden.\n\nHolt hat die mächtigsten und gefürchtetsten Bestien von Azeroth bezwungen und befehligt selbst viele starke Kreaturen. Seine Verbundenheit mit der Erdenmutter ist stark. Ihr könnt viel von ihm lernen. Viel Glück, $N.", objectives = "Sprecht mit Holt Thunderhorn auf der Anhöhe der Jäger in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6101] = { title = "Die Zähmung der Bestie", description = "Auf die Vielfalt der Natur kann man sich verlassen, $n. Sie ist insofern vorhersehbar, dass sie niemals gleich bleibt. Sie ist in konstantem Wandel.\n\nDie Aufgaben, die ich Euch gebe, werden Euch helfen, die enormen Unterschiede der Kreaturen zu erkennen, die Ihr als Eure Gefährten wählen könnt.\n\nNehmt diese Zähmrute und zähmt damit einen der pirschenden Nachtsäbler, die im Süden zu finden sind. Übt Eure Fertigkeiten als Jäger. Dann werdet Ihr die Übereinstimmungen und Unterschiede der Natur begreifen.", objectives = "Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6102] = { title = "Die Zähmung der Bestie", description = "Ihr habt zwei Kreaturen gezähmt, die am Boden leben, jetzt müsst Ihr eine zähmen, die am Himmel dahinzieht. Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen, die man westlich von hier findet. Übt Eure Fertigkeiten mit dieser mächtigen Eule an Eurer Seite.\n\nWenn Ihr zurückkehrt gebe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl als Gefährten zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", objectives = "Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6103] = { title = "Die Ausbildung des Tiers", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es zu trainieren.\n\nReist nach Darnassus. Dort müsst Ihr mit Jocaste sprechen, einer unserer angesehensten Jägerinnen. Sie gibt Euch die Fähigkeit, Euer neues Tier auszubilden, also sputet Euch.\n\nJocaste mag einen strengen Eindruck machen, freut sich aber stets, wenn sie den Aufstieg eines neuen Jägers verfolgen kann. Behandelt sie mit Respekt, dann wird sie Euch ebenso begegnen. Viel Glück, $n.", objectives = "Sprecht mit Jocaste in der Enklave des Cenarius in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6121] = { title = "Neue Lektionen", description = "Ihr seid jetzt bereit, alles über Gifte und die Macht zu lernen, die wir Druiden darüber haben, $N. Cenarius hat uns mit der Fähigkeit gesegnet, selbst die abscheulichsten Gifte mit einer Beschwörung auszutreiben. Mit dieser Gabe geht man nicht leichtfertig um... und damit Ihr diese Lektion lernt, müsst Ihr die Wirkung von Giften behandeln wie es ein Laie tun würde.\n\nReist nach Moonglade und sprecht mit Dendrite Starblaze. Er erwartet Eure Ankunft, um die Lektion zu beginnen.", objectives = "Reist nach Moonglade und sprecht mit Dendrite Starblaze im Dorf Nighthaven.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6122] = { title = "Die eigentliche Ursache", description = "Cliffspring Falls in Dunkelküste dient als wichtigste Trinkwasserquelle in der Region. Ich fürchte, jetzt ist es die primäre Ursache des Gifts, das der dortigen Fauna schadet, besonders dem Wild. Holt mit diesem Gefäß etwas Wasser vom Höhleneingang, aber seid vorsichtig, inzwischen hausen gefährliche Naga in einer Höhle bei den Wasserfällen.\n\nWenn Ihr es gefüllt habt, bringt es zu Alanndarian Nightsong in Auberdine. Sie bat um unsere Hilfe und Ihr werdet Euch gemeinsam mit ihr dieses Übels annehmen.", objectives = "Benutzt das leere Gefäß bei Cliffspring Falls und nehmt eine Wasserprobe vom Höhleneingang bei den Wasserfällen.\n\nBringt das gefüllte Gefäß von Cliffspring Falls zu Alanndarian Nightsong nach Auberdine in Dunkelküste.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6123] = { title = "Das Heilmittel sammeln", description = "Das Wasser wird Grundlage einer Heilsalbe sein, die ich für das Wild anrühre. Für die Heilwirkung benötige ich etwas Erdwurzel. Kräuterkundige wissen, wo man sie finden kann. Wenn wir Pech haben und Ihr keiner seid, müsst Ihr einen suchen, der uns weiterhilft.\n\nUnd der besseren Wirksamkeit wegen brauche ich etwas Lunarfungus. Es ist recht leicht, Lunarfungusblüten zu finden. In den Höhlen östlich von hier gedeihen sie reichlich. Moonkin, die neuerdings recht gereizt sind, hausen in diesen Höhlen, also seid vorsichtig.", objectives = "Bringt 5 Erdwurzeln und 12 Lunarfungi zu Alanndarian Nightsong in Auberdine, damit sie eine Heilsalbe machen kann.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6124] = { title = "Heilung der Kranken", description = "Die Salbe, die ich aus den Reagenzien herstellen konnte, die Ihr mir gebracht habt, reicht für zehn Dosen, $N. Ich arbeite weiter mit den Dorfbewohnern zusammen und versuche mehr Salbe herzustellen. Derweil möchte ich, dass Ihr uns einen Vorsprung verschafft. Rund um Dunkelküste wimmelt es von krankem Wild. Heilt es mit der Salbe von seinem Übel.\n\nDendrite Starblaze in Moonglade wird ganz sicher mit Euch reden wollen, wenn Ihr fertig seid. Bitte übermittelt dem Zirkel des Cenarius Auberdines Dank... und lasst mich Euch persönlich für Eure Hilfe danken!", objectives = "Benutzt die Tier-Heilsalbe bei 10 kranken Wildtieren rund um Dunkelküste. Das müsste sie heilen. Es wurde berichtet, dass krankes Wild südlich des Cliffspring, im Norden von Auberdine und bis hinunter in die südlichen Regionen von Dunkelküste, wo Ashenvale beginnt, aufgetaucht ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6125] = { title = "Macht über Gift", description = "Ihr habt gelernt, was es heißt, Vergiftungen ohne spirituelle Unterstützung zu heilen. Vergesst nicht, was andere auf sich nehmen müssen, wenn sie gegen Vergiftungen ankämpfen, wenn Ihr Eure neu erlangte Macht über Gift erhaltet.\n\nIhr solltet jetzt zu Mathrengyl Bearwalker in Darnassus zurückkehren, $N. Zweifellos hat er Euch wichtige Zauber beizubringen, da Ihr nun die Lektionen begriffen habt, die Ihr erhieltet.\n\nLebt wohl, junger Druide. Wir sprechen uns wieder.", objectives = "Kehrt zu Mathrengyl Bearwalker in der Enklave des Cenarius in Darnassus zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6126] = { title = "Neue Lektionen", description = "Ihr seid jetzt bereit, alles über Gifte und die Macht zu lernen, die wir Druiden darüber haben, $N. Cenarius hat uns mit der Fähigkeit gesegnet, selbst die abscheulichsten Gifte mit einer Beschwörung auszutreiben. Mit dieser Gabe geht man nicht leichtfertig um ... und damit Ihr diese Lektion lernt, müsst Ihr die Wirkung von Giften behandeln wie es ein Laie tun würde.\n\nReist nach Moonglade und sprecht mit Dendrite Starblaze. Er erwartet Eure Ankunft, um die Lektion zu beginnen.", objectives = "Reist nach Moonglade und sprecht mit Dendrite Starblaze im Dorf Nighthaven.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6127] = { title = "Die eigentliche Ursache", description = "Der Glutnebelgipfel nordwestlich von Crossroads ist höchstwahrscheinlich die Quelle, von wo aus sich das Gift verbreitet. Auf seinen luftigen Höhen gibt es Teiche, die das Wetter beeinflussen. Dieses Wasser wurde vermutlich durch Dämonen anbetende Burning Blade verunreinigt.\n\nEntnehmt dem Teich auf der Spitze des Gipfels mit diesem Behältnis eine Probe. Wenn es gefüllt ist, bringt es zu Tonga Runetotem in Crossroads. Er bat um unsere Hilfe und Ihr werdet Euch gemeinsam mit ihm dieses Übels annehmen.", objectives = "Benutzt die leere Glutnebelgipfelprobe beim Glutnebelgipfel und nehmt eine Wasserprobe vom Teich auf der Spitze des Gipfels.\n\nBringt das gefüllte Behältnis vom Glutnebelgipfel zu Tonga Runetotem in Crossroads im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6128] = { title = "Das Heilmittel sammeln", description = "Das Wasser wird Grundlage einer Heilsalbe sein, die ich für die Gazellen herstelle. Für die Heilwirkung benötige ich etwas Erdwurzel. Kräuterkundige wissen, wo man sie finden kann. Wenn Ihr nicht mit dieser Kunst vertraut seid, müsst Ihr einen suchen, der uns weiterhilft.\n\nDer Wirksamkeit wegen brauche ich zuletzt Kodohörner - Splitter und Bruchstücke reichen aber nicht aus. Kodos, mit denen Ihr fertig werdet, streifen durch den nördlichen Teil des Brachlands. Erlegt welche zum Wohle des Gleichgewichts, $N, und bringt mir die Hörner.", objectives = "Bringt 5 Erdwurzeln und 5 Kodohörner zu Tonga Runetotem in Crossroads, damit er eine Heilsalbe machen kann.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6129] = { title = "Heilung der Kranken", description = "Ich konnte genügend Salbe für zehn heilende Dosen machen, $N. Ich arbeite weiter mit den hiesigen Behörden zusammen und versuche, mehr Salbe herzustellen. Derweil möchte ich, dass Ihr uns einen Vorsprung verschafft. Rund um das nördliche Brachland wimmelt es von kranken Gazellen. Heilt sie mit der Salbe von ihrem Übel.\n\nDendrite Starblaze in Moonglade wird ganz sicher mit Euch reden wollen, wenn Ihr fertig seid. Bitte übermittelt dem Zirkel des Cenarius unseren Dank... und lasst mich Euch persönlich für Eure Hilfe danken!", objectives = "Benutzt die heilende Tiersalbe bei 10 kränklichen Gazellen im nördlichen Teil des Brachlandes. Das müsste sie heilen. Kränkliche Gazellen wurden überall nördlich der Ost-West-Straße durch Crossroads gesehen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6130] = { title = "Macht über Gift", description = "Ihr habt gelernt, was es heißt, Vergiftungen ohne spirituelle Unterstützung zu heilen. Vergesst nicht, was andere auf sich nehmen müssen, wenn sie gegen Vergiftungen ankämpfen, wenn Ihr Eure neu erlangte Macht über Gift erhaltet.\n\nIhr solltet jetzt zu Turak Runetotem in Thunder Bluff zurückkehren, $N. Zweifellos hat er Euch wichtige Zauber beizubringen, da Ihr nun die Lektionen begriffen habt, die Ihr erhieltet.\n\nLebt wohl, junger Druide. Wir sprechen uns wieder.", objectives = "Kehrt zu Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6132] = { title = "Holt mich hier raus!", description = "Holt mich hier raus!\n\nIch kam ins Tal der Speere, um mit den Maraudines zu sprechen. Ich dachte, ich könnte Geschäfte mit ihnen machen... aber sie reden einfach nicht mit mir! Ich glaube, sie möchten mich eher verspeisen!\n\nHolt mich hier raus, mein Bruder Hornizz wird es Euch reich vergelten! Er ist in unserem Lager neben dem Kodofriedhdof im Osten.\n\nBeeilen wir uns, $n. Es ist keine zwei Minuten her, da hörte ich einige Zentauren sagen, dass sie Holz für ihren Kochtopf sammeln möchten...", objectives = "Eskortiert Melizza Brimbuzzle und sprecht anschließend mit Hornizz Brimbuzzle beim Kodofriedhdof Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6133] = { title = "Das Ersuchen des Waldläuferlords", description = "Die Hochelfen der Quel’danil-Lodge haben etwas, das mir gehört, $C: Ein Dokument, das mein Leben als Sterblicher schildert.\n\nBevor Ihr fragt, Ihr seid wahrscheinlich nicht befugt, derlei Informationen zu bekommen. Macht einfach, was ich Euch sage, Wurm: Holt den Lebenslauf zurück.\n\nUnd, Schwachkopf, richtet so viel Not und Elend an, wie Ihr könnt. Lasst sie leiden ...", objectives = "Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Quel'Thalas-Registratur zurück. Der Gegenstand befindet sich irgendwo in der Quel'Lithien-Lodge.\n\nAußerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6134] = { title = "Geisterplasmasuche", description = "Im Südosten liegt ein Tal, das Tal der Knochen, das von den Geistern der Magram heimgesucht wird. Klingt gruselig, nicht wahr? Stellt Euch mal vor, wie sich die Magram erst gruseln müssen! Wenn wir Geisterenergie an jenem Ort einfangen könnten, wäre das den Zentauren sicher einiges wert.\n\nHier, nehmt diese Kiste mit Geistermagneten. Wenn Ihr einen zwischen den beiden großen Skeletten im Tal aufstellt, den toten Goliaths, dann werden sich Geister materialisieren und dorthin gehen. Nehmt Abstand, schaltet die Geister aus und holt Euch ihr Geisterplasma - das verkaufen wir den Magram.", objectives = "Bringt 8 Einheiten Geisterplasma und die Kiste mit den Geistermagneten zu Hornizz Brimbuzzle in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6135] = { title = "Dämmerschwinge, oh, wie ich Euch hasse...", description = "Bisher habt Ihr die Missionen abgeschlossen, die ich Euch aufgab, wenn Ihr auch nicht unbedingt ein Ausbund an Pünktlichkeit seid.\n\nIhr denkt wahrscheinlich, dass Ihr bereit für eine Herausforderung seid. Ja... ja, Schwachkopf, vielleicht seid Ihr wirklich für anspruchsvollere Missionen bereit.\n\nDämmerschwinge, der Albinofledermausdämon, streift nördlich von hier durch das Land. Spürt ihn auf und besiegt ihn. Kehrt mit einem Büschel seines weißen Fells zu mir zurück und Ihr sollt eine Belohnung erhalten.", objectives = "Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Blightcaller.\n\nMan sagt, dass Dämmerschwinge nördlich von hier durch das Land streift.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6136] = { title = "Der Korpulente", description = "Hinter der Hoffnung des Lichts, dem Lager der Argentumdämmerung, und westlich von Northdale, findet Ihr die wohlbeleibte Madenbestie Blutschlinger.\n\nIch habe ganze Regimenter an dieses Monster verloren. Sein Leibesumfang ist gewaltig! Je mehr er frisst, desto größer wird sein Appetit ...\n\nEs würde mir keine schlaflosen Nächte bereiten, sollte die Bestie Euch verschlingen, dennoch sähe ich es lieber, wenn Ihr der Sieger sein würdet. Ich empfehle, dass Ihr Euch in dieser Angelegenheit der Hilfe anderer versichert. Man weiß, dass Blutschlinger kleine Bataillone verschlungen hat, die töricht genug waren, ihn anzugreifen.", objectives = "Sucht in den nördlichen Wüsten der Östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Blightcaller zurück, sobald Ihr diese Mission erledigt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6141] = { title = "Bruder Anton", description = "Bruder Anton, mein Waffenbruder, hörte Gerüchte über einen Angriff der Untoten im fernen Kalimdor, in einem Land, das Desolace genannt wird. Anton buchte sofort eine Überfahrt dorthin, um die Bedrohung durch die Untoten zu lokalisieren und zu beseitigen!\n\nEr sucht Leute mit viel Tapferkeit und Entschlossenheit, die ihm dabei helfen. Wenn Ihr aufrichtigen Herzens seid, dann sprecht mit Anton. Er befindet sich in Desolace in einer Stadt der Allianz namens Nijelspitze.", objectives = "Sprecht mit Bruder Anton in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6142] = { title = "Muschelköder", description = "Ihr seht wahrlich aus wie ein Angler, $C! Ich angle zu gern - schon mein Leben lang. Als Köder eignet sich das Fleisch der weichschaligen Muschel am besten. Die Fische können ihm einfach nicht widerstehen. Wisst Ihr, was ich meine?\n\nOben im Norden findet Ihr ein Schiffswrack vor der Küste. In der Gegend wimmelt es von weichschaligen Muscheln. Wenn Ihr mir 10 Teile Fleisch der weichschaligen Muschel bringt, werde ich Euch etwas dafür geben.", objectives = "Sucht 10 Teile Fleisch der weichschaligen Muschel und bringt sie zu Mai'Lahii im Dorf Shadowprey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6143] = { title = "Andere Fische zu grillen", description = "Vielleicht habt Ihr es ja gehört, vielleicht auch nicht... meine Besatzung und ich waren vor der Insel Ranazjar fischen, nördlich des Schiffswracks vor der Küste im Norden. Wir haben immer dort gefischt, jetzt suche ich nur eine Möglichkeit, wie ich meine gefallenen Kameraden rächen kann.\n\nDie Naga haben uns eines Morgens angegriffen und alle außer mir getötet.\n\nDie Schuld lastet mir schwer auf der Seele, $C; ihr müsst losziehen und diese Naga für mich grillen. Ich werde Euch für die Mühe belohnen. Meint Ihr, Ihr könnt mir behilflich sein?", objectives = "Tötet 7 Myrmidonen der Zackenkämme, 7 Naga der Zackenkämme und 5 Zauberhexerinnen der Zackenkämme, dann sprecht in Desolace mit Drulzegar in Shadowprey.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6144] = { title = "Der Befehl", description = "Der Befehl ist gekommen, $C. Varimathras selbst hat verlangt, dass ich meine 'tüchtigsten' Agenten auf eine höchst diffizile taktische Mission in die Undercity schicke.\n\nLeider wurden meine tüchtigsten Agenten alle vor drei Jahren getötet. An ihrer Stelle habe ich eine Bande hirntoter Trottel.\n\n<Nathanos schaut Euch kalt an.>\n\nReist sofort zur Undercity und erstattet Varimathras Bericht. Macht mir keine Schande, $C!", objectives = "Reist in die Undercity und sprecht mit Varimathras.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6145] = { title = "Der Purpurrote Kurier", description = "So wie niemand ohne den Kopf überleben kann, kann der Kopf nicht ohne den Körper überleben. Die Verteidigungsanlagen des Scharlachroten Kreuzzugs in Stratholme sind fast unüberwindbar. Stattdessen müssen wir den Körper unter dem Kopf abschneiden.\n\nMeine Todespirscher haben Daten über die Aktivitäten des Kreuzzugs außerhalb von Stratholme gesammelt. Jeden Tag wird ein Bericht aus ihrer Befehlszentrale in Tyrs Hand geschickt. Dieser Bericht ist der Schlüssel, $R! Sucht den Purpurroten Kurier und beschafft diesen Bericht. Bringt ihn zu Nathanos.", objectives = "Kehrt in die östlichen Pestländer zurück und spürt den Purpurroten Kurier auf. Tötet den Kurier und schnappt Euch den Befehl des obersten Kreuzzüglers.\n\nBringt den Befehl zu Nathanos Blightcaller und wartet auf weitere Anweisungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6146] = { title = "Nathanos' List", description = "Ich habe diesen Befehl etwas modifiziert. Sollte unsere kleine List wirken, wird das Scharlachrote Orakel schutzlos sein und wir schlagen zu!\n\nPasst jetzt genau auf, $C. Ihr werdet diesen Befehl dem Kreuzzüglerlord Valdelmar überbringen.\n\nWie? Ihr drückt ihm das Ding in die Hand, Schwachkopf.\n\nBringt den Befehl und diesen faulen Apfel nach Tyrs Hand. Wenn Ihr in der Stadt seid, dann esst den Apfel. Ihr werdet Euch in etwas verwandeln, das für Menschen ... verträglicher ist. Nehmt den Befehl und übergebt ihn dem Kreuzzüglerlord Valdelmar.", objectives = "Reist nach Tyrs Hand, südöstlich der Siedlung Marris. Dort angekommen beißt in den faulen Apfel. In der Verkleidung des Scharlachroten Kreuzzugs überbringt Ihr Lord Valdelmar den Befehl des obersten Kreuzzüglers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6147] = { title = "Kehrt zu Nathanos zurück.", description = "Der oberste Kreuzzügler bringt eine ungewöhnliche Bitte vor. Hrm, wie dem auch sei... was er verlangt, soll geschehen. Kehrt zur Scharlachroten Bastion zurück und lasst ihn wissen, dass das Orakel sich bald auf den Weg machen wird.\n\nWir werden alle Vorsichtsmaßnahmen treffen, damit sie es unbeschadet nach Stratholme schafft.", objectives = "Kehrt mit der neuen Information zu Nathanos Blightcaller zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6148] = { title = "Das scharlachrote Orakel Demetria", description = "Demetria ist die oberste Beraterin des obersten Kreuzzüglers. Ihrer 'überirdischen' Sinne wegen nennt man sie das Orakel. Sie hat den Kreuzzug erfolgreich zu mehreren Siegen gegen die Geißel geführt.\n\nWir konnten sie zwar mit dieser List herauslocken, aber wenn sie wirklich eine übersinnliche Begabung besitzt, wird sie zweifellos mit Ärger rechnen. Ihr werdet für diesen 'Ärger' sorgen.\n\nSpürt das Orakel auf und beendet ihre Existenz. Sie müssten in diesem Moment von Tyrs Hand aufbrechen. Macht mich stolz, Wurm.", objectives = "Der Scharlachrote Kreuzzug ist unterwegs. Irgendwo auf der Straße von Tyrs Hand nach Stratholme findet Ihr das Orakel Demetria und ihr Gefolge. Jagt sie und tötet sie. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr erfolgreich wart.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6161] = { title = "Nehmt Rackmores Schatz!", description = "Aus Rackmores Logbuch geht hervor, dass sein Schiff zur Festung Feathermoon segelte, als es von seefahrenden Kreaturen angegriffen wurde. Er versteckte seine Truhe auf der Insel Ranazjar, damit sein Schatz dem Feind nicht in die Hände fallen sollte.\n\nZwei Schlüssel, ein silberner und ein goldener, sind erforderlich, um die Truhe zu öffnen. Diese Schlüssel gingen verloren, doch wenn Schlüssel und Truhe gefunden werden, winkt ein Schatz!", objectives = "Sucht Rackmores Silberschlüssel. Sucht Rackmores Goldschlüssel. Sucht und öffnet Rackmores Truhe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6162] = { title = "Eines Ehemanns letzter Kampf", description = "Mein Gatte reiste unserem Klan zu Ehren durch den Teufelswald und kämpfte gegen den Schattenrat und andere verderbte Monstrositäten!\n\nAls er dem Tod viele Male entronnen war, erhielt ich einen Brief von ihm, in dem stand, dass ein Druide ihn um Beistand gegen einen großen beschmutzten Furbolg namens Oberanführer Ror gebeten hatte - man hörte nie wieder etwas von ihnen.\n\nIch möchte die Klauenhand dieses Ror, $N. Er soll dafür büßen, dass er mich zur Witwe gemacht hat! Ich glaube, die Kreatur ist im Süden... nahe der Grenze von Ashenvale.", objectives = "Tötet Oberanführer Ror und bringt seine Klaue zu Dreka'Sur beim Blutgiftposten im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6163] = { title = "Ramstein", description = "Ich war überwältigt. Ich stand in dieser Siedlung... und blieb standhaft bei der Verteidigung von Lordaeron. Der Hof und alles darauf wurde von einer gigantischen Welle der Geißel belagert.\n\nDer Dreck. Der Schmutz. Er stand über mir und die Eingeweide hingen ihm aus einem klaffenden Loch in der Brust.\n\nIch erwachte als Geißel. Lange Zeit war ich hilflos. Meine Gedanken waren mit denen des Lichkönigs verschmolzen.\n\nSie kam zu mir... irgendwo, irgendwie wusste ich es. Frei.\n\nDoch jetzt muss ich meine Rache haben - Rache an dem, der mir das Leben genommen hat. Vernichtet ihn.", objectives = "Reist nach Stratholme und tötet Ramstein den Würger. Bringt seinen Kopf als Souvenir zu Nathanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6164] = { title = "Augustus' Rezeptbuch", description = "Ich bin jetzt bereit für's Geschäftliche! Was wollt Ihr?\n\nOh, Moment mal... ohne mein Quittungsbuch kann ich kein Geschäft eröffnen. Wie soll ich ohne mein Quittungsbuch den Überblick behalten?\n\nIch muss es in der Stadt gelassen haben. Ich hatte ein Zimmer im Gasthaus... dort muss das Buch sein.\n\nBringt mir mein Buch. Bitte, bringt es mir! Bringt mir mein Buch und Ihr werdet sehen! Ich eröffne mein Geschäft und Ihr werdet sehen, dass meine Preise der WAHNSINN sind!", objectives = "Bringt Augustus' Quittungsbuch zu Augustus dem Meschuggenen im Schreckenstal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6181] = { title = "Eine eilige Nachricht", description = "Wir bekommen zwar nicht viel Unterstützung von Stormwind direkt, aber ich habe einen Kontaktmann in der Stadt, der uns mit Rüstungen versorgt. Sein Name ist Osric Strang. Sein Geschäft, Begrenzte Immunität, liegt in der Altstadt von Stormwind.\n\nUnser Vorrat an Rüstung schwindet, ich muss bei Osric mehr bestellen. Könnt Ihr ihm diese Notiz bringen?\n\nDer schnellste Weg nach Stormwind führt über Thor, unseren Greifenmeister. Er ist unten am Hügel; bringt ihm meine Notiz und nehmt dann einen Greifen nach Stormwind.", objectives = "Bringt Lewis' Notiz zu Thor dem Greifenmeister.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6182] = { title = "Der Erste und Letzte", description = "Nathanos Marris war der erste und letzte Waldläuferlord der Menschen. Ein Schüler von Sylvanas Windrunner, die heute Bansheekönigin der Verlassenen ist.\n\nWir dachten, Nathanos sei fünf Jahre zuvor bei der Verteidigung von Lordaeron in der Schlacht gefallen. Sein Leichnam wurde zwar nie gefunden, aber man ging davon aus, dass er es nicht aus den östlichen Pestländern hinaus geschafft hatte.\n\nMathias Shaw hat sein Verschwinden untersucht und könnte neue Informationen haben. Meldet Euch sofort bei ihm. Er lebt in der Altstadt, in der Kaserne.", objectives = "Sprecht mit Meister Mathias Shaw in der Altstadt von Stormwind. Er wohnt in der Kaserne.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6183] = { title = "Ehret die Toten", description = "Fünf meiner besten Agenten wurden dem Fall Marris zugeteilt. Einer kam zurück und starb drei Tage später im Schlaf.\n\nDie wenigen Informationen, die wir aus ihm herausbekamen, waren unverständliches Gestammel. Wir haben zwei Worte verstanden: 'Nathanos' und 'Blightcaller'.\n\nIch habe nicht genügend Leute, um die Ermittlungen fortzusetzen, und Ravenholdt ist uns nicht behilflich. Wir müssen der Sache auf den Grund gehen, und wenn es nur ist, damit wir den Familien der Verstorbenen Trost spenden können. Werdet Ihr helfen?", objectives = "Sprecht wieder mit Mathias Shaw, wenn Ihr seine Aufgabe annehmen wollt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6184] = { title = "Flint Schattenmoor", description = "Die einzige Information, die wir bislang haben, ist die, dass Nathanos Marris von diesem Blightcaller ermordet worden sein könnte. Wir gehen davon aus, dass Blightcaller derselbe Teufel ist, der meine Agenten beseitigt hat.\n\nFlint Shadowmore, ein weiterer Agent des SI:7, ist im Lager der Allianz an der Chillwindspitze, westliche Pestländer, stationiert. Sucht ihn auf. Er wird Euch in die aktuelle Situation in den Pestländern einweihen und Euch einen Auftrag erteilen.\n\nViel Glück, $N.", objectives = "Reist zur Chillwindspitze in den Westlichen Pestländern und trefft Euren Kontaktmann Flint Shadowmore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6185] = { title = "Die Östlichen Pestländer", description = "Wie gesagt, Eure erste Mission ist eine Aufklärungsmission. Nichts Kompliziertes, $N. Ihr müsst in die östlichen Pestländer reisen und nach Hinweisen auf diesen Blightcaller suchen.\n\nHaltet nach Informationen über unsere vermissten Agenten Ausschau. Wir müssen davon ausgehen, dass sie tot sind, und wenn sie tot sind, muss es Leichen geben ... irgendwo.\n\n<Flint schluckt schwer.>\n\nAlle SI:7-Agenten tragen diese Insignien.\n\n<Flint zeigt Euch seine SI:7-Insignien.>\n\nBringt alle zu mir zurück, die Ihr finden könnt.", objectives = "Sucht in den östlichen Pestländern nach Hinweisen auf den 'Blightcaller' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Shadowmore an der Chillwindspitze.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6186] = { title = "Der Blightcaller kommt", description = "<Flints Gesicht wird schlagartig leichenblass.>\n\nNa... Nathanos ist das gewesen? Nathanos ist der Blightcaller?\n\nWarum? Er war... war so edel – ein Waldläuferlord, den alle geachtet haben. Der einzige Mensch, der je bei den Hochelfen ausgebildet wurde. Der soll jetzt ein ruchloser Agent der Verlassenen sein?\n\nIch... Ich bin untröstlich, dass ich das von Euch verlangen muss, $N, aber Hochlord Fordragon muss unverzüglich über diese Wendung der Ereignisse informiert werden. Bitte kehrt nach Stormwind zurück und überbringt diese Nachricht.", objectives = "Kehrt nach Stormwind zurück und informiert Hochlord Bolvar Fordragon über das Schicksal von Nathanos Marris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6187] = { title = "Ordnung muss wieder hergestellt werden", description = "Wisst Ihr, wie viele Waldläuferlords es auf dieser Welt gibt? Wie viele menschliche Waldläuferlords jemals existiert haben?\n\nNathanos' Errungenschaften waren beispiellos. Er war ein taktisches Genie und führte die Allianz in einem Jahrzehnt der Konflikte zu vielen Siegen.\n\nUnd jetzt... der Held der Verlassenen.\n\nNein. Das darf nicht sein. Die Ordnung muss wieder hergestellt werden.\n\nVersammelt eine Armee, $N. Kehrt mit Eurer Armee in die Pestländer zurück und vernichtet Blightcaller.\n\nIch wünsche Euch Glück, $N. Das werdet Ihr für diesen Kampf wahrlich brauchen.", objectives = "Stellt eine Armee auf und reist zu den östlichen Pestländern. Beginnt einen gnadenlosen Angriff auf Nathanos Blightcaller und jeden Abschaum der Horde, der ihn beschützen mag.\n\nBewahrt einen klaren Kopf, $N. Die Horde wird den Waldläuferlord mit dem Leben verteidigen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6261] = { title = "Dungar Trinkfest", description = "$N, ich habe alles, worum Lewis gebeten hat, in diese Kiste gepackt. Würdet Ihr sie ihm bringen?\n\nWenn Ihr bereits mit Thor in Westfall gesprochen habt, dann könnt Ihr einen Greif zurück zu ihm nehmen. Dungar Longdrink ist unser Greifenmeister drüben im Handelsdistrikt.\n\nSprecht mit Dungar, dann bringt diese Kiste auf dem schnellsten Weg zu Lewis. Wir möchten nicht, dass unsere kämpfenden Männer und Frauen in Westfall ohne neue Ausrüstung sind!", objectives = "Bringt Osrics Kiste zu Dungar Longdrink dem Greifenmeister.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6281] = { title = "Weiter nach Stormwind", description = "Gegen eine geringe Gebühr könnt Ihr einen Greifen nach Stormwind nehmen und so Lewis' Notiz zu Osric bringen. Einen schnelleren Weg gibt es nicht.\n\nWenn Euch das akzeptabel erscheint, sprecht mich wieder an, sobald Ihr bereit seid für den Flug. Das kostet eine Kleinigkeit, aber glaubt mir, es lohnt sich!", objectives = "Bucht einen Greifenritt bei Greifenmeister Thor, dann bringt Lewis' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6282] = { title = "Harpyien drohen", description = "Tauren sind die stolzen Beschützer dieser Länder. Zweifellos könnt Ihr erraten, warum mich die Anzahl der Harpyien hier im Steinkrallengebirge so beunruhigt.\n\nDie Blutfurien sind die Ursache für die zunehmende Zahl von Harpyien in Kalimdor. Sie bedrängen jede Lebensform und hindern Unschuldige daran, ihre Grenzen zu verlassen.\n\nIhr müsst die Harpyen für mich dezimieren, $N!", objectives = "Maggran Earthbinder in Sonnenfels möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6283] = { title = "Blutfuriengeschlecht", description = "Es genügt nicht, die Anzahl der Blutfurienharpyien zu verringern. Die einzig wahre Kur für ihre Krankheit wäre es, ihre Anführerin zu beseitigen, die Zerfetzerin der Blutfurien!\n\nFür diese dreckigen Kreaturen ist sie so etwas wie eine Königin. Tötet sie und ihre Zahl wird ganz gewiss abnehmen.\n\nGeht zurück zum Verbrannten Tal, dort findet Ihr sie in den westlichen Hügeln. Sie wird nicht leicht zu bezwingen sein, aber die Belohnung ist groß.", objectives = "Maggran in Sonnenfels möchte, dass Ihr die Zerfetzerin der Blutfurien beseitigt und ihre sterblichen Überreste als Beweis für Eure Tat mitbringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6284] = { title = "Arachnophobie", description = "Warnung: Betretet Sishir Canyon westlich von hier auf eigene Gefahr.\n\nBesseleth und ihre achtbeinigen Kinder des Waldes haben diesen Canyon zu ihrem eingesponnen Unterschlupf erkoren.\n\nMaggran Earthbinder in Sonnenfels hat ein Kopfgeld auf Besseleth ausgesetzt. Tötet sie und bringt einen Beweis Eurer Tat zu Maggran. Dort werdet Ihr eine Belohnung erhalten, wenn Ihr der achtbeinigen Gefahr ein Ende gemacht habt.", objectives = "Tötet Besseleth und bringt Besseleths Fangzahn zu Maggran in Sonnenfels.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6285] = { title = "Zurück zu Lewis", description = "Der Greifenmeister in Westfall heißt Thor. Falls Ihr schon mit ihm gesprochen habt, dann könnt Ihr einen meiner Greifen zu ihm bringen.\n\nDas hier sollte man unbedingt wissen: Greifen sind stets so ausgebildet, dass sie in ihre Hauptstadt fliegen, aber sie bringen Euch nur zu einem außerörtlichen Greifenmeister, wenn Ihr schon einmal dort gewesen seid.\n\nIhr seid bereits bei Thor gewesen, sprecht daher einfach wieder mit mir, wenn Ihr bereit seid, einen Greifen nach Westfall zu nehmen. Dort könnt Ihr Osrics Kiste bei Rüstmeister Lewis abliefern.", objectives = "Bucht einen Greifenritt zur Späherkuppe bei Greifenmeister Dungar Longdrink, dann bringt Osrics Kiste zu Lewis an der Späherkuppe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6301] = { title = "Zyklus der Wiedergeburt", description = "Industrielle Gier und ständige Kriege haben die Länder des Steinkrallengebirges verwüstet. Nur der Segen der Erdenmutter kann solch eine Verletzung heilen.\n\n$N, Ihr müsst für mich ein spezielles Samenkorn suchen, Gaeasamenkorn. Man findet diese Samenkörner nur hier im Steinkrallengebirge, nördlich von Sonnenfels am Mirkfallonsee, in der Nähe des Ufers.\n\nWenn Ihr mir die Samenkörner bringt, werde ich sie mit schamanistischer Macht magieerfüllen, um ihr Wachstum zu beschleunigen.", objectives = "Tammra Windfield in Sonnenfels möchte, dass Ihr 10 Gaeasamenkörner sammelt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6321] = { title = "Nachschub für das Grabmal", description = "Exekutor Hadrec bat mich, eine Inventur unserer Ausrüstung beim Grabmal durchzuführen. Da die Geißel und Schlimmeres in den Wäldern lauert, möchte er nicht, dass den Todeswachen Ausrüstung fehlt, die sie brauchen.\n\nIch habe festgestellt, dass wir im Großen und Ganzen gut bestückt sind, aber wir brauchen mehr Waffen als Ersatz für die, die wir auf dem Feld verloren haben.\n\nHier eine Anforderungsliste der benötigten Dinge für den Waffenhändler Gordon Wendham in Undercity. Bringt die Anforderungsliste zum Fledermausmeister Karos Razok und sprecht mit ihm über den Transport zur Undercity.", objectives = "Bringt Podrigs Liste zu Karos Razok.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6322] = { title = "Michael Garrett", description = "Ich habe den Nachschub für das Grabmal in diese Kiste getan. Wenn Ihr das Grabmal schon besucht und mit dem Fledermausmeister gesprochen habt, könnt Ihr mit einer Fledermaus zu ihm reiten.\n\nSprecht mit Michael Garret, dem Fledermausmeister von Undercity. Er kann Euch eine Fledermaus zum Grabmal zur Verfügung stellen.", objectives = "Bringt Gordons Kiste zu Michael Garret.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6323] = { title = "Flug nach Undercity", description = "Gegen eine geringe Gebühr kann Euch eine meiner Fledermäuse zur Undercity bringen. Sprecht mich wieder an, wenn Ihr bereit seid, damit wir Euren Transport vereinbaren können.\n\nIhr findet Gordon Wendham im Handwerksviertel von Undercity. In diesem Viertel landet auch meine Fledermaus.", objectives = "Bucht einen Fledermausritt zur Undercity bei Fledermausmeister Karos Razok und bringt dann Podrigs Anforderungsliste zu Gordon Wendham in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6324] = { title = "Rückkehr zu Podrig", description = "Der Fledermausmeister im Grabmal ist Karos Razok. Wenn Ihr schon bei ihm gewesen seid, dann gebe ich Euch eine Fledermaus, damit Ihr zu ihm fliegen könnt.\n\nUnsere Fledermäuse fliegen stets zur Undercity, aber um zu entlegeneren Orten zu reisen, muss ihr Reiter zuerst die Gegend besuchen und mit dem dortigen Fledermausmeister sprechen.\n\nIhr habt Karos im Grabmal getroffen, daher könnt Ihr jetzt mit Fledermäusen dorthin fliegen. Sprecht wieder mit mir, wenn Ihr bereit seid.", objectives = "Bucht einen Fledermausritt zum Grabmal bei Fledermausmeister Michael Garret und bringt dann Gordons Kiste zu Todeswache Podrig beim Grabmal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6341] = { title = "Die Arten von Teldrassil", description = "Den Anglern des Dorfes Rut'theran geht es sehr gut, denn die Fische dort sind extrem groß und zahlreich. Ich würde die hier vorkommenden Arten gern mit denen des Festlandes vergleichen.\n\nIch habe eine Sammlung von Fischgräten und Schuppen, die ich gern zu einem Kollegen von mir in Dunkelküste bringen würde. Er heißt Laird und ist ein Fischverkäufer im Dorf Auberdine.\n\nBringt meine Sammlung zu unserem Hippogryphenmeister Vesprystus und besprecht mit ihm, wie Ihr am besten nach Auberdine kommt.", objectives = "Bringt Nessas Sammlung zu Vesprystus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6342] = { title = "Flug nach Auberdine", description = "Von Rut'theran gibt es zwei Reisemöglichkeiten nach Auberdine: mit der Fähre und mit einem Hippogryphen. Beide sind schnell und zuverlässig, aber wenn Ihr noch nicht mit dem Hippogryphen nach Auberdine geflogen seid, solltet Ihr das schleunigst nachholen.\n\nEin guter Rat: Sprecht in jeder Stadt, in der es einen gibt, mit dem Hippogryphenmeister. Sobald Ihr mit dem Meister gesprochen habt, könnt Ihr von anderen Städten aus dorthin fliegen.\n\nHier ist Nessas Sammlung. Sprecht wieder mit mir, wenn Ihr bereit seid, nach Auberdine zu fliegen und Nessas Sammlung bei Laird abzuliefern.", objectives = "Bucht bei Hippogryphenmeister Vesprystus einen Hippogryphen nach Auberdine und bringt dann Nessas Sammlung zu Laird.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6343] = { title = "Rückkehr zu Nessa", description = "Ich muss Nessa eine Antwort schicken. Sie interessiert sich bestimmt dafür, wie sehr sich die Fische hier von denen an der Küste Teldrassils unterscheiden. Wir können nur vermuten, was die Ursache sein mag, ich persönlich hege jedoch die Befürchtung, dass der Weltbaum die Natur um sich herum beeinflusst!\n\nBitte bringt Nessa diese Antwort. Wenn Ihr einen Hippogryphen zurück nach Rut'theran nehmen wollt, dann sprecht mit der Hippogryphenmeisterin Caylais Moonfeather. Wenn Ihr die Fähre nehmen wollt, so ist auch das kein Problem: Es legt regelmäßig eine vom Dock im Nordwesten ab.", objectives = "Bringt Lairds Antwort zu Nessa Shadowsong.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6344] = { title = "Nessa Schattensang", description = "Eine Freundin von mir, Nessa Shadowsong, ist Anglerbedarfshändlerin in Rut'theran. Sie muss ein Päckchen nach Dunkelküste bringen und sucht jemanden, der ihr hilft.\n\nWenn Ihr zu Nessa wollt, dann müsst Ihr in Darnassus das Portal nach Rut'theran benutzen. Ihr findet das Portal westlich der Tempelgärten.", objectives = "Sprecht mit Nessa Shadowsong.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6361] = { title = "Ein Bündel Bälge", description = "Ich habe ein Bündel Bälge von Tieren des Brachlands und muss es nach Thunder Bluff bringen. Dort fertigt Ahanu, ein Kollege, Lederwaren aus diesen Häuten an.\n\nBringt Ihr ihm die Bälge für mich?\n\nDer schnellste Weg nach Thunder Bluff ist auf dem Rücken eines Windreiters. Bringt das Bündel Bälge zu Devrak, unserem Windreitermeister in Crossroads, und sprecht mit ihm über den Transport nach Thunder Bluff.", objectives = "Bringt das Bündel Bälge zu Windreitermeister Devrak in Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6362] = { title = "Flug nach Thunder Bluff", description = "Für ein kleines Entgelt gebe ich Euch einen Windreiter nach Thunder Bluff. Es gibt kein schnelleres Transportmittel in die Stadt!\n\nSollte das akzeptabel sein, sprecht wieder mit mir, wenn Ihr abreisefertig seid.\n\nWenn Ihr diese Bälge zu Ahanu bringen wollt, dann schätze ich, er ist in Hewas Waffenkammer am Fundament des Windreiterturms in Thunder Bluff. Und genau dort werdet Ihr landen!", objectives = "Bucht einen Windreiter nach Thunder Bluff bei Windreitermeister Devrak und bringt dann das Bündel Bälge zu Ahanu in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6363] = { title = "Tal der Windreitermeister", description = "Ich habe Lederwaren für Jahan zum Verkauf in Crossroads vorbereitet. Würdet Ihr sie ihm bringen?\n\nWenn Ihr schon in Crossroads gewesen seid und mit dem dortigen Windreitermeister gesprochen habt, dann könnt Ihr mit einem unserer Thunder-Bluff-Windreiter zu ihm zurück.\n\nBringt die Lederwaren zu Tal, unserem Windreitermeister in Thunder Bluff, und sprecht mit ihm über den Transport nach Crossroads.", objectives = "Bringt Ahanus Lederwaren zu Tal in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6364] = { title = "Rückkehr zu Jahan", description = "Um zu einer Stadt zu fliegen, müsst Ihr schon einmal dort gewesen sein und mit dem Windreitermeister dieser Stadt gesprochen haben. Ihr seid in Crossroads gewesen und habt mit dem Windreitermeister Devrak gesprochen, daher könnt Ihr gegen ein geringes Entgelt von hier mit einem unserer Windreiter zu ihm.\n\nSprecht wieder mit mir, wenn Ihr bereit seid. In Crossroads könnt Ihr die Lederwaren zu Jahan Hawkwing bringen.", objectives = "Bucht einen Windreiter nach Crossroads bei Windreitermeister Tal und bringt dann Ahanus Lederwaren zu Jahan Hawkwing.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6365] = { title = "Fleisch für Orgrimmar", description = "Ich habe hier ausgewählte Fleischstücke, die ich einer Freundin schicken möchte. Ihr Name ist Gryshka, sie ist die Gastwirtin in Orgrimmar. Würdet Ihr das Fleisch für mich abliefern?\n\nDas schnellste Transportmittel nach Orgrimmar ist ein Windreiter. Bringt das Fleisch zu Crossroads Windreitermeister Devrak und sprecht mit ihm über den Transport nach Orgrimmar.", objectives = "Bringt Zarghs Fleisch zu Devrak in Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6381] = { title = "Neues Leben", description = "Wie Ihr sehen könnt, $C, ist der Zyklus des Lebens eine mächtige Sache, auch wenn das Land Schmerzen leidet. Jetzt müssen wir unseren Teil leisten, um ihm zu helfen. Ihr müsst diese Samen im Zentrum der Zerstörung pflanzen, im Westen, im Verbrannten Tal. Aber seid wachsam, denn Harpyien und Feuerelementare verseuchen das vernarbte Land noch immer.\n\nNehmt diese verzauberten Gaeasamenkörner und pflanzt sie in fruchtbare Erdhügel, $n. Der Zyklus des Lebens muss weitergehen!", objectives = "Pflanzt 10 Gaeasamenkörner in Gaeaerdhügel und sprecht dann mit Tammra in Sonnenfels.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6382] = { title = "Die Jagd in Ashenvale", description = "Eure Kraft beeindruckt mich, $C. Die Entschlossenheit, mit der Ihr Euch der Jagd zuwendet, erfüllt mich mit der Gewissheit, dass Ihr Euch größerem Wild... und größeren Herausforderungen zuwenden könnt.\n\nDer Wald von Ashenvale ist eine große, ungezähmte Wildnis, der die Horde ihren Willen aufzuzwingen trachtet, sowohl politisch wie auch spirituell. Wenn Ihr Euch in einem unerforschten Land beweisen wollt, dann sucht die Führung von Senani Thunderheart im Splintertreeposten. Der Außenposten liegt nördlich des Pfads, der aus dem Brachland führt.", objectives = "Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6383] = { title = "Die Jagd in Ashenvale", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6384] = { title = "Flug nach Orgrimmar", description = "Für eine Handvoll Münzen lasse ich Euch mit einem Windreiter nach Orgrimmar bringen. Wenn Ihr dort eintrefft, bringt Zarghs Fleisch zu Gryshka. Ihr Gasthaus liegt im Tal der Stärke, nicht weit vom Himmelsturm entfernt, wo mein Windreiter Euch absetzen wird.\n\nSprecht wieder mit mir, wenn Ihr bereit für die Reise seid.", objectives = "Bucht einen Windreiter nach Orgrimmar bei Windreitermeister Devrak und bringt dann Zarghs Fleisch zu Gryshka in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6385] = { title = "Doras der Windreitermeister", description = "Ich habe Zargh einen Dankesbrief geschrieben. Könnt Ihr ihn für mich zustellen? Wenn Ihr schon in Crossroads gewesen seid und mit dem dortigen Windreitermeister gesprochen habt, dann könnt Ihr mit einem Windreiter dorthin zurück fliegen.\n\nBringt meinen Brief zu Forak, dem Windreitermeister von Orgrimmar, und sprecht mit ihm über den Transport nach Crossroads.", objectives = "Bringt Gryshkas Brief zu Doras in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6386] = { title = "Kehrt nach Crossroads zurück", description = "Meine Windreiter wurden ausgebildet, an viele verschiedene Orte zu fliegen, wenn Ihr schon an diesem Ort gewesen seid und mit dem Windreitermeister dort gesprochen habt.\n\nIhr seid in Crossroads gewesen und habt mit dem Windreitermeister Devrak gesprochen, daher könnt Ihr jetzt direkt zu ihm fliegen. Wenn Ihr in Crossroads seid, könnt Ihr Gryshkas Brief zu Zargh bringen.\n\nSprecht wieder mit mir, wenn Ihr bereit zum Aufbruch seid.", objectives = "Bucht einen Windreiter nach Crossroads bei Windreitermeister Doras und bringt dann Gryshkas Brief zu Zargh in Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6387] = { title = "Ehrenstudenten", description = "Ich sehe viele junge Zwerge vor meiner Tür, die begierig sind, den Bergbau zu erlernen. Und wenn ein Minenarbeiter eines mehr als alles andere braucht, dann ist das eine Hacke!\n\nIch habe eine Liste von Bergbaustudenten mit vorzüglichen Abschlussprüfungen, die sich eine Ehrenhacke verdient haben. Bringt meine Liste zu Golnir Bouldertoe in Ironforge. Er wird die Hacken fertigmachen.\n\nDas schnellste Transportmittel nach Ironforge ist ein Greif, also bringt die Liste Thorgrum Borrelson, unserem Greifenmeister, und sprecht mit ihm über den Transport nach Ironforge.", objectives = "Bringt Brocks Liste zu Thorgrum Borrelson in Thelsamar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6388] = { title = "Gryth Thurden", description = "Hier sind die Ehrenhacken für Brocks Studenten. Wenn Ihr schon in Thelsamar gewesen seid, dann solltet Ihr mit einem Greifen dorthin zurückfliegen!\n\nBringt die Hacken zu unserem Greifenmeister Gryth Thurden und sprecht mit ihm über die Rückreise nach Thelsamar.", objectives = "Bringt die Ehrenhacken zu Gryth Thurden in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6389] = { title = "Eine Plage komme über Euch", description = "Ihr seht Euch in dem Sägewerk nach etwas um, mit dem Ihr das Fass öffnen könnt. Ihr findet ein Stemmeisen, das aussieht, als würde es damit gehen.\n\nIhr nehmt die Beine in die Hand und betet, dass Ihr aus dem Sägewerk entwischen könnt, bevor die Termiten Euch erwischen.", objectives = "Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Nathaniel Dumah im Chillwind-Posten in den westlichen Pestländern zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6390] = { title = "Eine Plage komme über Euch", description = "Ihr seht Euch in dem Sägewerk nach etwas um, mit dem Ihr das Fass öffnen könnt. Ihr findet ein Stemmeisen, das aussieht, als würde es damit gehen.\n\nIhr nehmt die Beine in die Hand und betet, dass Ihr aus dem Sägewerk entwischen könnt, bevor die Termiten Euch erwischen.", objectives = "Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Mickey Levine im Bollwerk in Tirisfal zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6391] = { title = "Flug nach Ironforge", description = "Für nur ein paar Münzen bringt Euch einer meiner Greifen nach Ironforge. Bringt dann Brocks Liste zu Golnir Bouldertoe. Ihr findet ihn in der Deepmountain-Bergbaugilde. Sie liegt im Distrikt der Großen Schmiede von Ironforge, und genau dort setzt Euch mein Greif ab!\n\nSprecht wieder mit mir, wenn Ihr bereit für die Reise seid.", objectives = "Bucht einen Greifen nach Ironforge von Greifenmeister Thorgrum Borrelson, dann bringt Brocks Liste zu Golnir Bouldertoe in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6392] = { title = "Rückkehr zu Brock", description = "Für ein geringes Entgelt könnt Ihr einen Greifenritt nach Thelsamar buchen... wenn Ihr schon einmal dort gewesen seid. Greifen fliegen nur zu Orten, an denen Ihr schon einmal gewesen seid, sprecht also mit jedem Greifenmeister, den Ihr seht, dann könnt Ihr später direkt zu ihm fliegen.\n\nIhr seid schon bei Thorgrum, dem Greifenmeister von Thelsamar, gewesen, daher könnt Ihr jetzt zu ihm zurückkehren. Wenn Ihr in Thelsamar seid, könnt Ihr Brock Stoneseeker die Hacken bringen.\n\nSprecht mit mir, wenn Ihr bereit zum Aufbruch seid.", objectives = "Bucht einen Greifen nach Thelsamar bei Greifenmeister Gryth Thurden, dann bringt die Ehrenhacken zu Brock Stoneseeker in Thelsamar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6393] = { title = "Krieg der Elementare", description = "Das Tribunal der Gezeiten hat mich geschickt, um den Feuerelementaren hier im Steinkrallengebirge den Krieg zu erklären. Neptulon der Gezeitenjäger, der Lord aller Wasserelementare hier, hat ein persönliches Interesse daran, dass unsere feurigen Vettern ausgelöscht werden.\n\n$n, Ihr könnt mir helfen, die Gunst des Tribunals zu erringen, indem Ihr die Feuerelementare im Verbrannten Tal vernichtet. Wenn Feuerelementare zerstört werden, hinterlassen sie Pyrophore. Bringt sie mir, dann werde ich Euch belohnen.", objectives = "Bringt 10 Pyrophore zu Tsunaman in Sonnenfels.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6394] = { title = "Thazz'rils Hacke", description = "$N, Ihr seid ein $R, auf den man sich verlassen kann. Würdet Ihr wohl eine weitere Aufgabe für mich erledigen?\n\nVor einiger Zeit suchte ich in einer Höhle im Norden nach Mineralien und vergaß dort meine Lieblingshacke. Als ich später dorthin zurückkehrte, hausten tückische Bestien in dieser Höhle! Würdet Ihr diese Höhle aufsuchen, es ist der Koven der Burning Blade, und meine Hacke holen?\n\nIch habe sie in einer Kammer mit Wasserfällen gelassen. Meine Hacke ist verzaubert, daher könnt Ihr sie im Dunkeln sehen und müsst Euch keine Sorgen machen, wie Ihr sie findet ... nur diejenigen, die sie bewachen, müsst Ihr fürchten!", objectives = "Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6395] = { title = "Marlas letzter Wunsch", description = "Meine Freundin Marla Fipps lebte vor der Seuche mit ihrem Mann Samuel zusammen, doch als die Seuche kam, erlag Samuel ihr und lief zur Geißel über.\n\nMarla wurde der Untod erspart, doch sie starb durch die Hand ihres jetzt hirnlosen Mannes. Aber ihre Liebe war so stark, dass sie sterbend den letzten Wunsch äußerte, zusammen mit ihrem geliebten Samuel begraben zu werden.\n\nSamuel Fipps streift durch ein verwüstetes Lager nordöstlich von Deathknell. Besiegt ihn und erfüllt Marlas Wunsch: Begrabt ihn in ihrem Grab in der ersten Reihe unseres Friedhofs.", objectives = "Bringt Samuel Fipps' sterbliche Überreste zu Marlas Grab und kehrt dann zu Novize Elreth zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6401] = { title = "Kaya lebt", description = "Teilt Tammra Windfield, Kayas Tante, die in Sonnenfels lebt, die gute Nachricht mit! Kaya lebt! Wir hatten sie nach dem brutalen Angriff auf unser Dorf schon verloren geglaubt. Folgt dem Pfad nach Westen, um nach Sonnenfels zu gelangen.", objectives = "Teilt Tammra Windfield, die in Sonnenfels lebt, die gute Nachricht mit.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6402] = { title = "Treffen in Stormwind", description = "Ihr sollt Euch an den Toren von Stormwind mit Windsor treffen.\n\nWas Windsor Euch eröffnen wird, wird das gesamte Königreich in den Grundfesten erschüttern!\n\nVersucht aber nicht, allein dorthin zu gehen, $N. Ihr müsst eine ganze Armee zusammenscharen! Versammelt Eure Mitstreiter. Zu den Waffen!", objectives = "Reist nach Stormwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marshal Windsor über Eure Ankunft informiert.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6403] = { title = "Die große Maskerade", description = "Das war vielleicht ein Abenteuer. Ich schulde Euch großen Dank. Vielleicht, wenn alles gesagt und getan ist...\n\nWie Ihr zweifellos schon bemerkt haben werdet, sind Lady Prestor und Onyxia ein und dieselbe Person. Sie ist die Brut von Deathwing, Zwillingsschwester des Tyrannen der Spitze, Nefarian.\n\nViel zu lange schon hat sie ihren gierigen Blick auf unser Königreich gerichtet. Sogar der Hochlord steht schon unter dem Bann ihrer Zaubertricks - eine Marionette. Heute wird damit Schluss gemacht... Der Bann wird gebrochen.\n\nSorgt Euch nicht, denn gemeinsam werden wir siegen!\n\nSeid Ihr bereit?", objectives = "Folgt Reginald Windsor durch Stormwind. Schützt ihn vor Gefahren!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6421] = { title = "Steinschlagklamm", description = "Irgendetwas stimmt hier im Steinkrallengebirge nicht. Spürt Ihr die Spannung, die in der Luft liegt, $n?\n\nSüdlich von hier liegt eine tiefe Höhle in der Steinschlagklamm. Die Kobolde dort schürfen wie wild nach einem seltenen Kristall, dem so genannten Resonit. Ich möchte, dass Ihr mir ein paar Erzproben bringt, damit ich herausfinden kann, was in dieser Höhle vor sich geht. Ich hätte auch gern, dass Ihr die Tiefen dieser Höhle untersucht.\n\nGeht nun, $C, es ist von größter Bedeutung, dass ich in Erfahrung bringe, welche Bösartigkeiten unter diesen Bergen lauern.", objectives = "Erkundet die Tiefen der Höhle in der Steinschlagklamm und bringt Mor'rogal in Sonnenfels 10 Resonitkristalle, damit er sie untersuchen kann.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6441] = { title = "Satyrhörner", description = "He! Ich bin auf der Durchreise nach Ratchet, habe ganz Ashenvale durchquert und mich entschlossen, hier in Splintertree Rast zu machen. Ich suche immer nach guten Gelegenheiten und es scheint mir, dass in Ratchet zurzeit Satyrhörner sehr gefragt sind.\n\nNachdem ich mich hier ein bisschen umgehört habe, glaube ich, dass die Satyrn in Night Run, Satyrnaar und Xavian genau die Art Hörner besitzen, die ich suche. Ich kann mich mit diesen Satyrn nicht messen... aber Ihr!\n\nIch sag Euch was: Wenn Ihr mir die Hörner bringt, soll es Euer Schaden nicht sein.", objectives = "Sammelt für Pixel im Splintertreeposten 16 Satyrhörner.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6442] = { title = "Die Naga am Zoramstrand", description = "Entlang der Küste hier lauert das Böse, $R.\n\nEs ist die Ruhestätte der untergegangenen Stadt Zoram, die vor langer Zeit zerstört wurde und im Meer versank. Sie war verloren und fast vergessen.\n\nJetzt allerdings sind die Naga zurückgekehrt, aber warum, wissen wir nicht. Die Gründe sind jedoch auch nicht weiter wichtig. Wir müssen das Land verteidigen, um das wir so hart gekämpft haben.\n\nBringt mir 20 ihrer Köpfe! Treibt die Naga in die Tiefen zurück!", objectives = "Bringt Marukai am Zoramstrand 20 Köpfe von Rächerflossen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6461] = { title = "Blutfresser", description = "Wir Trolle hier am Malaka'jin haben von dem Land profitiert. Das Steinkrallengebirge bietet reiche Jagdgründe, von denen wir leben können.\n\nIn letzter Zeit jedoch scheinen wir die falschen Gäste angezogen zu haben... Die Spinnen in diesen Bergen haben nachts unsere Lager überfallen, um uns unsere Jagdbeute zu stehlen.\n\nWenn Ihr uns helfen könntet, diese schrecklichen Bestien zu töten, würden wir hier am Malaka'jin zutiefst in Eurer Schuld stehen. Die Spinnen sind überall im Steinkrallengebirge - geht einfach von hier aus nach Norden, dann werdet Ihr sehen, was ich meine.", objectives = "Xen'zilla am Malaka'jin möchte, dass Ihr 10 Kluftmooskrabbler und 7 Kluftmoosgiftspucker tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6462] = { title = "Troll-Glücksbringer", description = "Meine Leute waren mit vielen hochheiligen Troll-Glücksbringern im Gepäck unterwegs, aber dann wurden sie von Distelfellfurbolgs angegriffen und getötet, bevor sie Zoram'gar erreichen konnten! Diese elenden Furbolgs!\n\nIch vermisse meine getöteten Brüder und Schwestern, aber wir werden uns im Jenseits wiedersehen. Die Troll-Glücksbringer haben in dieser Welt jedoch hohen Wert. Es ist eine Schande, dass sie jetzt in den Händen der Furbolgs sind!\n\n$N, Ihr müsst diese Glücksbringer zurückholen! Sie befinden sich in Kisten in der Höhle, einer Höhle der Distelfelle am Ende des Lagers der Distelfelle nördlich von Astranaar.", objectives = "Bringt Mitsuwa im Zoram'gar-Außenposten 8 Troll-Glücksbringer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6481] = { title = "Der Irdene erhebt sich", description = "Ihr habt eine dunkle Bedrohung für das Land entdeckt, $C. Das Resonitfässlein, das Ihr in der Höhle gefunden habt, birgt einen schlummernden Irdenen namens Goggeroc.\n\nIch habe die Mixtur der Resonitkristalle, die Ihr gesammelt habt, mit Hilfe meiner Schamanenkräfte verändert. Nehmt den verzauberten Resonitkristall und zerschmettert das Resonitfässlein, in dem sich der Irdene befindet.\n\nWenn Goggeroc erwacht, wird er noch geschwächt sein... erschlagt ihn, $N!", objectives = "Öffnet das Resonitfässlein mit dem verzauberten Resonitkristall und tötet Goggeroc. Kehrt mit der Vollzugsmeldung und dem verzauberten Resonitkristall zu Mor'rogal zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6482] = { title = "Freiheit für Ruul", description = "Huch? Wer seid Ihr?\n\n$N? Ihr seid kein Furbolg. Sie sind verflucht! Sie hielten mich für einen Bären und fingen mich. Jetzt lassen sie mich verhungern! Meine Kraft schwindet...\n\nHelft mir zu entkommen, dann sprecht mit meiner Schwester Yama im Splintertreeposten im Osten.\n\n$N! Ich muss entkommen!", objectives = "Begleitet Ruul und sprecht dann mit Yama Snowhoof im Splintertreeposten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6501] = { title = "Das Großdrachenauge", description = "Ich habe leider nicht mehr als ein Fragment des zertrümmerten Medaillons zu bieten.\n\nIhr müsst einen anderen aus dem Geblüt der Großdrachen finden, der bereit ist, Euch zu helfen, einen neuen Schlüssel zu schmieden. Sobald Ihr diesen Schlüssel habt, müsst Ihr zum Drachensumpf in den Marschen von Dustwallow reisen. Dort findet Ihr ihr Lager, $N.\n\nWo Ihr weitere Klans finden könnt, die gewillt wären, Euch zu helfen? Das weiß ich leider nicht ... Es soll angeblich welche geben. Einige sollen sogar unter uns leben und arbeiten, getarnt als Angehörige der humanoiden Völker. Ich wünsche Euch Glück.", objectives = "Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[6502] = { title = "Drachenfeueramulett", description = "Das ist ein Stück des Großdrachen. Eine Schuppe - verzaubert und transformiert. Als Ganzes hätte sie Zugang zum Hort der Bestie verschafft. Zertrümmert ist sie nutzlos.\n\nEs ist möglich, den Gegenstand zu reparieren, aber dazu wäre das Blut eines schwarzen Großdrachenhelden erforderlich. Es gibt einen... Er ist bekannt als General Drakkisath, Herrscher über die Drachenbrutarmeen von Nefarian. Vielleicht habt Ihr schon von ihm gehört?\n\nBringt mir sein Blut, $R, dann verzaubere ich das Fragment in etwas, das Euch Zugang zu Onyxias Hort verschaffen wird.", objectives = "Ihr müsst das Blut des schwarzen Großdrachen-Helden von General Drakkisath bekommen. Ihr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Blackrockspitze.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
